/* Fragenkatalog der Meister-Lern-App (Entwurf, Rechtsstand 17.10.2026).
   Quelle: die drei Google-Tabellen "Fragenkatalog Meister-Lern-App" (+ Erweiterung 1 und 2).
   Felder: id, hf = Teil-Handlungsfeld, q = Frage, o = Antworten A bis D, a = richtige Antwort (0 = A),
   e = Erklärung, l = Rechtsgrundlage, t = Thema, s = Schwierigkeit, p = Prüfstatus.
   Neue Fragen einfach als weitere Zeile anhängen. */
const Q = [
 {id:"T3-1-01",hf:"III-1",q:"Welche Aussage zur Bilanz ist richtig?",o:["Die Aktivseite zeigt, woher das Kapital stammt.","Die Summe der Aktivseite ist gleich der Summe der Passivseite.","Das Eigenkapital steht auf der Aktivseite.","Die Bilanz zeigt die Aufwendungen und Erträge eines Jahres."],a:1,e:"Aktiva zeigen die Mittelverwendung, Passiva die Mittelherkunft. Beide Seiten sind immer gleich groß. Aufwand und Ertrag stehen in der Gewinn- und Verlustrechnung.",l:"HGB § 242, § 266",t:"Bilanz",s:"leicht",p:"Entwurf, Fachprüfung offen"},
 {id:"T3-1-03",hf:"III-1",q:"Ein Betrieb hat 60.000 € Eigenkapital und eine Bilanzsumme von 240.000 €. Wie hoch ist die Eigenkapitalquote?",o:["20 %","40 %","25 %","75 %"],a:2,e:"Eigenkapitalquote = Eigenkapital : Bilanzsumme × 100 = 60.000 : 240.000 × 100 = 25 %.",l:"Kennzahl, keine Rechtsnorm",t:"Kennzahlen",s:"leicht",p:"Entwurf, Fachprüfung offen"},
 {id:"T3-1-04",hf:"III-1",q:"Ein Betrieb hat 20.000 € flüssige Mittel und 40.000 € kurzfristige Verbindlichkeiten. Wie hoch ist die Liquidität 1. Grades?",o:["200 %","100 %","25 %","50 %"],a:3,e:"Liquidität 1. Grades = flüssige Mittel : kurzfristige Verbindlichkeiten × 100 = 20.000 : 40.000 × 100 = 50 %.",l:"Kennzahl, keine Rechtsnorm",t:"Kennzahlen",s:"mittel",p:"Entwurf, Fachprüfung offen"},
 {id:"T3-1-05",hf:"III-1",q:"Der Verkaufspreis eines Produkts beträgt 95 €, die variablen Stückkosten betragen 60 €. Wie hoch ist der Deckungsbeitrag je Stück?",o:["35 €","60 €","95 €","155 €"],a:0,e:"Deckungsbeitrag je Stück = Preis minus variable Stückkosten = 95 € − 60 € = 35 €.",l:"Kostenrechnung",t:"Kalkulation",s:"leicht",p:"Entwurf, Fachprüfung offen"},
 {id:"T3-1-06",hf:"III-1",q:"Fixkosten: 12.000 € im Jahr. Verkaufspreis: 80 € je Stück. Variable Stückkosten: 50 €. Ab welcher Menge arbeitet der Betrieb ohne Verlust?",o:["150 Stück","240 Stück","400 Stück","600 Stück"],a:2,e:"Break-even-Menge = Fixkosten : Deckungsbeitrag je Stück = 12.000 : (80 − 50) = 400 Stück.",l:"Kostenrechnung",t:"Break-even",s:"mittel",p:"Entwurf, Fachprüfung offen"},
 {id:"T3-1-08",hf:"III-1",q:"Wie lange müssen Bilanzen und Jahresabschlüsse aufbewahrt werden?",o:["3 Jahre","6 Jahre","10 Jahre","8 Jahre"],a:2,e:"Jahresabschlüsse, Inventare und Handelsbücher werden 10 Jahre aufbewahrt.",l:"HGB § 257 Abs. 4, AO § 147 Abs. 3",t:"Aufbewahrung",s:"leicht",p:"Quelle belegt"},
 {id:"T3-1-09",hf:"III-1",q:"Wie lange müssen Buchungsbelege wie Rechnungen und Quittungen, die ab 2025 ausgestellt wurden, in der Regel aufbewahrt werden?",o:["6 Jahre","8 Jahre","10 Jahre","12 Jahre"],a:1,e:"Seit dem Vierten Bürokratieentlastungsgesetz gilt für Buchungsbelege eine Frist von 8 Jahren.",l:"HGB § 257 Abs. 4, AO § 147 Abs. 3",t:"Aufbewahrung",s:"mittel",p:"Quelle belegt"},
 {id:"T3-1-10",hf:"III-1",q:"Wie lange müssen Handelsbriefe (zum Beispiel Angebote und Auftragsbestätigungen) aufbewahrt werden?",o:["6 Jahre","8 Jahre","10 Jahre","3 Jahre"],a:0,e:"Empfangene und abgesandte Handelsbriefe werden 6 Jahre aufbewahrt.",l:"HGB § 257 Abs. 4",t:"Aufbewahrung",s:"leicht",p:"Quelle belegt"},
 {id:"T3-1-11",hf:"III-1",q:"Welche Zuordnung bei der SWOT-Analyse ist richtig?",o:["Stärken und Chancen sind innere Faktoren des Betriebs.","Schwächen und Chancen sind innere Faktoren des Betriebs.","Risiken und Stärken kommen aus dem Marktumfeld.","Stärken und Schwächen sind innere Faktoren, Chancen und Risiken kommen aus dem Umfeld."],a:3,e:"Stärken und Schwächen beschreiben den Betrieb selbst. Chancen und Risiken entstehen im Markt, bei Kunden, Wettbewerbern und im rechtlichen Umfeld.",l:"Strategische Analyse",t:"SWOT-Analyse",s:"leicht",p:"Entwurf, Fachprüfung offen"},
 {id:"T3-1-12",hf:"III-1",q:"Ein Betrieb wirbt mit falschen Angaben über seine Leistungen. Welches Gesetz regelt vor allem diesen Fall?",o:["Gesetz gegen den unlauteren Wettbewerb (UWG)","Berufsbildungsgesetz (BBiG)","Insolvenzordnung (InsO)","Handwerksordnung (HwO)"],a:0,e:"Das UWG verbietet irreführende und andere unlautere geschäftliche Handlungen. Mitbewerber und Verbände können abmahnen.",l:"UWG",t:"Wettbewerbsrecht",s:"leicht",p:"Entwurf, Fachprüfung offen"},
 {id:"T3-1-13",hf:"III-1",q:"Was bedeutet der Zusatz e. K. im Firmennamen?",o:["Eingetragene Kooperation","Eingetragener Kaufmann","Eingetragener Kommanditist","Europäische Kapitalgesellschaft"],a:1,e:"Der Zusatz kennzeichnet einen im Handelsregister eingetragenen Einzelkaufmann.",l:"HGB § 19",t:"Handelsrecht",s:"leicht",p:"Entwurf, Fachprüfung offen"},
 {id:"T3-1-14",hf:"III-1",q:"Ein Betrieb erzielt 400.000 € Umsatz und 24.000 € Gewinn. Wie hoch ist die Umsatzrentabilität?",o:["4 %","16,7 %","6 %","24 %"],a:2,e:"Umsatzrentabilität = Gewinn : Umsatz × 100. Also 24.000 : 400.000 × 100 = 6 %.",l:"Betriebswirtschaftliche Kennzahl",t:"Kennzahlen",s:"leicht",p:"Entwurf, Fachprüfung offen"},
 {id:"T3-1-15",hf:"III-1",q:"Ein Betrieb erzielt 18.000 € Gewinn bei 120.000 € Eigenkapital. Wie hoch ist die Eigenkapitalrentabilität?",o:["6,7 %","18 %","150 %","15 %"],a:3,e:"Eigenkapitalrentabilität = Gewinn : Eigenkapital × 100. Also 18.000 : 120.000 × 100 = 15 %.",l:"Betriebswirtschaftliche Kennzahl",t:"Kennzahlen",s:"mittel",p:"Entwurf, Fachprüfung offen"},
 {id:"T3-1-16",hf:"III-1",q:"Welche Kosten sind in der Regel variable Kosten?",o:["Hallenmiete","Versicherungsprämie","Materialverbrauch für Aufträge","Gehalt der Büroleitung"],a:2,e:"Variable Kosten ändern sich mit der Leistungsmenge, zum Beispiel Material. Miete, Versicherung und Gehälter fallen unabhängig von der Menge an (Fixkosten).",l:"Kosten- und Leistungsrechnung",t:"Kostenarten",s:"leicht",p:"Entwurf, Fachprüfung offen"},
 {id:"T3-1-18",hf:"III-1",q:"Eine Maschine kostet 48.000 € und wird linear über 8 Jahre ohne Restwert abgeschrieben. Wie hoch ist die jährliche Abschreibung?",o:["4.800 €","8.000 €","12.000 €","6.000 €"],a:3,e:"Lineare Abschreibung = Anschaffungskosten : Nutzungsdauer. Also 48.000 : 8 = 6.000 € pro Jahr.",l:"Rechnungswesen",t:"Abschreibung",s:"leicht",p:"Entwurf, Fachprüfung offen"},
 {id:"T3-1-19",hf:"III-1",q:"Eine Rechnung über 5.000 € wird innerhalb der Skontofrist mit 2 % Skonto bezahlt. Welchen Betrag überweist der Kunde?",o:["5.100 €","4.990 €","4.500 €","4.900 €"],a:3,e:"2 % von 5.000 € sind 100 €. Der Kunde überweist 5.000 € minus 100 € = 4.900 €.",l:"Rechnungswesen",t:"Skonto",s:"leicht",p:"Entwurf, Fachprüfung offen"},
 {id:"T3-1-20",hf:"III-1",q:"Ein Betrieb hat Umsatzsteuer aus Ausgangsrechnungen von 9.500 € und Vorsteuer aus Eingangsrechnungen von 6.000 €. Wie hoch ist die Zahllast?",o:["15.500 €","3.500 €","6.000 €","9.500 €"],a:1,e:"Zahllast = Umsatzsteuer minus Vorsteuer. Also 9.500 € minus 6.000 € = 3.500 €, die an das Finanzamt gezahlt werden.",l:"UStG",t:"Umsatzsteuer",s:"mittel",p:"Entwurf, Fachprüfung offen"},
 {id:"T3-1-21",hf:"III-1",q:"Wie wird ein Geschäftsvorfall in der doppelten Buchführung erfasst?",o:["Nur auf einem Konto","Auf mindestens zwei Konten, im Soll und im Haben mit gleichem Gesamtbetrag","Nur im Kassenbuch","Nur auf Bestandskonten"],a:1,e:"Jede Buchung berührt mindestens zwei Konten, die Summe der Sollbuchungen ist gleich der Summe der Habenbuchungen.",l:"HGB § 238 ff.",t:"Buchführung",s:"mittel",p:"Entwurf, Fachprüfung offen"},
 {id:"T3-1-25",hf:"III-1",q:"Was ist die kurzfristige Preisuntergrenze eines Produkts?",o:["Die gesamten Selbstkosten","Die Fixkosten","Die variablen Stückkosten","Der Preis des Wettbewerbers"],a:2,e:"Kurzfristig muss der Preis mindestens die variablen Stückkosten decken, sonst wird der Verlust mit jedem Verkauf größer. Langfristig müssen alle Kosten gedeckt sein.",l:"Kosten- und Leistungsrechnung",t:"Preisuntergrenze",s:"mittel",p:"Entwurf, Fachprüfung offen"},
 {id:"T3-1-26",hf:"III-1",q:"Die Selbstkosten eines Auftrags betragen 8.000 €. Es soll ein Gewinn von 10 % auf die Selbstkosten aufgeschlagen werden. Wie hoch ist der Netto-Angebotspreis?",o:["8.100 €","8.800 €","8.880 €","9.520 €"],a:1,e:"10 % von 8.000 € sind 800 €. Netto-Angebotspreis = 8.000 € + 800 € = 8.800 €.",l:"Kosten- und Leistungsrechnung",t:"Kalkulation",s:"leicht",p:"Entwurf, Fachprüfung offen"},
 {id:"T3-1-27",hf:"III-1",q:"Ein Netto-Angebotspreis beträgt 1.000 €. Wie hoch ist der Bruttopreis bei 19 % Umsatzsteuer?",o:["1.019 €","1.810 €","1.190 €","1.900 €"],a:2,e:"19 % von 1.000 € sind 190 €. Bruttopreis = 1.000 € + 190 € = 1.190 €.",l:"UStG",t:"Umsatzsteuer",s:"leicht",p:"Entwurf, Fachprüfung offen"},
 {id:"T3-1-28",hf:"III-1",q:"In welcher Phase des Produktlebenszyklus sind die Umsätze noch gering und die Kosten für Werbung und Entwicklung hoch?",o:["Einführungsphase","Reifephase","Sättigungsphase","Rückgangsphase"],a:0,e:"In der Einführungsphase muss das Produkt bekannt gemacht werden. Der Umsatz steigt erst in der Wachstumsphase deutlich.",l:"Marketing-Grundlagen",t:"Produktlebenszyklus",s:"leicht",p:"Entwurf, Fachprüfung offen"},
 {id:"T3-1-29",hf:"III-1",q:"Ein Betrieb hat jährliche Gesamtkosten von 120.000 € und 3.000 produktive Stunden. Wie hoch sind die Selbstkosten je produktiver Stunde?",o:["30 €","36 €","40 €","45 €"],a:2,e:"Selbstkosten je Stunde = Gesamtkosten : produktive Stunden. Also 120.000 € : 3.000 Stunden = 40 € je Stunde.",l:"Kosten- und Leistungsrechnung",t:"Stundenverrechnungssatz",s:"leicht",p:"Rechnung nachgerechnet, Fachprüfung offen"},
 {id:"T3-1-30",hf:"III-1",q:"Die Selbstkosten betragen 40 € je Stunde. Es wird ein Gewinnzuschlag von 8 % aufgeschlagen. Wie hoch ist der Netto-Stundenverrechnungssatz?",o:["43,20 €","48,00 €","40,80 €","44,00 €"],a:0,e:"8 % von 40 € sind 3,20 €. Netto-Satz = 40,00 € + 3,20 € = 43,20 €.",l:"Kosten- und Leistungsrechnung",t:"Stundenverrechnungssatz",s:"leicht",p:"Rechnung nachgerechnet, Fachprüfung offen"},
 {id:"T3-1-31",hf:"III-1",q:"Die Materialeinzelkosten eines Auftrags betragen 2.000 €. Der Materialgemeinkostenzuschlag beträgt 15 %. Wie hoch sind die Materialkosten insgesamt?",o:["2.015 €","2.150 €","2.300 €","2.600 €"],a:2,e:"15 % von 2.000 € sind 300 €. Materialkosten insgesamt = 2.000 € + 300 € = 2.300 €.",l:"Kosten- und Leistungsrechnung",t:"Zuschlagskalkulation",s:"leicht",p:"Rechnung nachgerechnet, Fachprüfung offen"},
 {id:"T3-1-32",hf:"III-1",q:"Ein Betrieb hat 180.000 € Fremdkapital und 60.000 € Eigenkapital. Wie hoch ist der Verschuldungsgrad?",o:["33 %","75 %","300 %","3 %"],a:2,e:"Verschuldungsgrad = Fremdkapital : Eigenkapital × 100. Also 180.000 : 60.000 × 100 = 300 %.",l:"Betriebswirtschaftliche Kennzahl",t:"Kennzahlen",s:"mittel",p:"Rechnung nachgerechnet, Fachprüfung offen"},
 {id:"T3-1-33",hf:"III-1",q:"Ein Betrieb hat 30.000 € Gewinn und 12.000 € Abschreibungen. Wie hoch ist der vereinfachte Cashflow?",o:["18.000 €","30.000 €","42.000 €","360.000 €"],a:2,e:"Vereinfachter Cashflow = Gewinn + Abschreibungen, weil Abschreibungen Aufwand ohne Auszahlung sind. Also 30.000 € + 12.000 € = 42.000 €.",l:"Betriebswirtschaftliche Kennzahl",t:"Kennzahlen",s:"mittel",p:"Rechnung nachgerechnet, Fachprüfung offen"},
 {id:"T3-1-34",hf:"III-1",q:"Die Fixkosten betragen 30.000 € im Jahr, die Deckungsbeitragsquote beträgt 40 %. Ab welchem Umsatz arbeitet der Betrieb ohne Verlust?",o:["12.000 €","75.000 €","120.000 €","30.000 €"],a:1,e:"Die Deckungsbeitragsquote sagt, wie viel von jedem Euro Umsatz nach Abzug der variablen Kosten übrig bleibt, hier 40 Cent. Davon müssen die Fixkosten bezahlt werden. Umsatz an der Gewinnschwelle (Break-even) = Fixkosten : Deckungsbeitragsquote. Also 30.000 € : 0,40 = 75.000 €.",l:"Kosten- und Leistungsrechnung",t:"Break-even",s:"schwer",p:"Rechnung nachgerechnet, Fachprüfung offen"},
 {id:"T3-1-35",hf:"III-1",q:"Der Listenpreis beträgt 2.000 €. Der Lieferant gewährt 10 % Rabatt und bei Zahlung innerhalb der Frist 2 % Skonto auf den Rechnungsbetrag. Wie hoch ist der Zahlbetrag?",o:["1.764 €","1.760 €","1.800 €","1.960 €"],a:0,e:"Nach Rabatt: 2.000 € × 0,90 = 1.800 €. Nach Skonto: 1.800 € × 0,98 = 1.764 €.",l:"Rechnungswesen",t:"Einkauf",s:"mittel",p:"Rechnung nachgerechnet, Fachprüfung offen"},
 {id:"T3-1-36",hf:"III-1",q:"Ein Rechnungsbetrag beträgt brutto 2.380 € inklusive 19 % Umsatzsteuer. Wie hoch ist der Nettobetrag?",o:["1.928 €","2.000 €","2.142 €","2.380 €"],a:1,e:"Nettobetrag = Bruttobetrag : 1,19. Also 2.380 € : 1,19 = 2.000 €.",l:"UStG",t:"Umsatzsteuer",s:"mittel",p:"Rechnung nachgerechnet, Fachprüfung offen"},
 {id:"T3-1-37",hf:"III-1",q:"Der Materialeinsatz beträgt im Jahr 120.000 €, der durchschnittliche Lagerbestand 20.000 €. Wie hoch ist die Lagerumschlagshäufigkeit?",o:["0,17","6","12","100"],a:1,e:"Lagerumschlag = Materialeinsatz : durchschnittlicher Lagerbestand. Also 120.000 € : 20.000 € = 6-mal pro Jahr.",l:"Materialwirtschaft",t:"Lagerkennzahlen",s:"mittel",p:"Rechnung nachgerechnet, Fachprüfung offen"},
 {id:"T3-1-38",hf:"III-1",q:"Ein Betrieb hat im Jahr Einnahmen von 95.000 € und Ausgaben von 71.000 €. Wie hoch ist der Gewinn nach der Einnahmen-Überschuss-Rechnung?",o:["24.000 €","71.000 €","95.000 €","166.000 €"],a:0,e:"Bei der Einnahmen-Überschuss-Rechnung gilt Einnahmen minus Ausgaben. Also 95.000 € minus 71.000 € = 24.000 €.",l:"EStG § 4 Abs. 3",t:"Gewinnermittlung",s:"leicht",p:"Rechnung nachgerechnet, Fachprüfung offen"},
 {id:"T3-1-39",hf:"III-1",q:"Was kennzeichnet A-Güter in der ABC-Analyse?",o:["Hoher Wertanteil bei geringem Mengenanteil","Geringer Wertanteil bei hohem Mengenanteil","Hoher Wertanteil bei hohem Mengenanteil","Kein Wertanteil"],a:0,e:"A-Güter machen einen großen Teil des Einkaufswerts bei kleiner Menge aus und werden besonders sorgfältig disponiert.",l:"Materialwirtschaft",t:"ABC-Analyse",s:"leicht",p:"Entwurf, Fachprüfung offen"},
 {id:"T3-1-40",hf:"III-1",q:"Das betriebsnotwendige Kapital beträgt 50.000 €. Es wird mit 6 % kalkulatorisch verzinst. Wie hoch sind die kalkulatorischen Zinsen pro Jahr?",o:["300 €","3.000 €","8.333 €","30.000 €"],a:1,e:"Kalkulatorische Zinsen = betriebsnotwendiges Kapital × Zinssatz. Also 50.000 € × 6 % = 3.000 €. Merkhilfe: 1 % von 50.000 € sind 500 €, mal 6 sind 3.000 €.",l:"Kosten- und Leistungsrechnung",t:"Kalkulatorische Kosten",s:"leicht",p:"Rechnung nachgerechnet, Fachprüfung offen"},
 {id:"T3-1-41",hf:"III-1",q:"Ein Betrieb verkauft 500 Stück mit einem Deckungsbeitrag von 24 € je Stück. Die Fixkosten betragen 9.000 €. Wie hoch ist das Betriebsergebnis?",o:["3.000 €","9.000 €","12.000 €","21.000 €"],a:0,e:"Gesamt-Deckungsbeitrag = 500 × 24 € = 12.000 €. Betriebsergebnis = 12.000 € minus 9.000 € = 3.000 €.",l:"Kosten- und Leistungsrechnung",t:"Deckungsbeitrag",s:"mittel",p:"Rechnung nachgerechnet, Fachprüfung offen"},
 {id:"T3-2-01",hf:"III-2",q:"Wo muss sich ein Betrieb eintragen lassen, der ein zulassungspflichtiges Handwerk selbstständig ausübt?",o:["Im Gewerbezentralregister","In der Handwerksrolle der Handwerkskammer","In der Lehrlingsrolle der Innung","Nur im Handelsregister"],a:1,e:"Der selbstständige Betrieb eines zulassungspflichtigen Handwerks ist nur nach Eintragung in die Handwerksrolle erlaubt.",l:"HwO § 1",t:"Handwerksrecht",s:"mittel",p:"Entwurf, Fachprüfung offen"},
 {id:"T3-2-02",hf:"III-2",q:"Bei welcher Stelle wird ein Gewerbe angemeldet?",o:["Beim Finanzamt","Beim Gewerbeamt der Gemeinde","Beim Amtsgericht","Bei der Berufsgenossenschaft"],a:1,e:"Die Anzeige des Gewerbes erfolgt beim zuständigen Gewerbeamt, in der Regel bei der Gemeinde oder Stadt.",l:"GewO § 14",t:"Gewerbeanmeldung",s:"leicht",p:"Entwurf, Fachprüfung offen"},
 {id:"T3-2-03",hf:"III-2",q:"Welche Aussage zu Handwerkskammer und Innung ist richtig?",o:["Beide Mitgliedschaften sind freiwillig.","Die Mitgliedschaft in der Handwerkskammer ist Pflicht, die in der Innung freiwillig.","Die Mitgliedschaft in der Innung ist Pflicht, die in der Handwerkskammer freiwillig.","Beide Mitgliedschaften sind Pflicht."],a:1,e:"Die Handwerkskammer ist eine Körperschaft des öffentlichen Rechts mit Pflichtmitgliedschaft der Handwerksbetriebe. Die Innung ist ein freiwilliger Zusammenschluss.",l:"HwO",t:"Handwerksorganisation",s:"leicht",p:"Entwurf, Fachprüfung offen"},
 {id:"T3-2-04",hf:"III-2",q:"Wer haftet bei einer OHG für die Schulden der Gesellschaft?",o:["Nur die Gesellschaft mit dem Gesellschaftsvermögen","Nur der Geschäftsführer","Alle Gesellschafter unbeschränkt mit ihrem Privatvermögen","Alle Gesellschafter höchstens in Höhe ihrer Einlage"],a:2,e:"Die Gesellschafter einer OHG haften den Gläubigern persönlich, unbeschränkt und gesamtschuldnerisch.",l:"HGB § 126",t:"Rechtsform",s:"mittel",p:"Entwurf, Fachprüfung offen"},
 {id:"T3-2-05",hf:"III-2",q:"Wie haftet ein Kommanditist in der KG?",o:["Unbeschränkt wie ein Komplementär","Beschränkt auf seine Hafteinlage","Unbeschränkt, sobald er im Handelsregister steht","Nur bei Insolvenz"],a:1,e:"Der Kommanditist haftet nur bis zur Höhe seiner Einlage. Ist sie geleistet, ist die persönliche Haftung ausgeschlossen.",l:"HGB § 171",t:"Rechtsform",s:"mittel",p:"Entwurf, Fachprüfung offen"},
 {id:"T3-2-06",hf:"III-2",q:"Wie hoch ist das gesetzliche Mindeststammkapital einer GmbH?",o:["1 €","10.000 €","25.000 €","50.000 €"],a:2,e:"Das Stammkapital einer GmbH muss mindestens 25.000 € betragen. 1 € reicht nur bei der UG (haftungsbeschränkt).",l:"GmbHG § 5 Abs. 1",t:"Rechtsform",s:"leicht",p:"Entwurf, Fachprüfung offen"},
 {id:"T3-2-07",hf:"III-2",q:"Welche Rechtsform kann schon mit einem Stammkapital von 1 € gegründet werden?",o:["GmbH","Unternehmergesellschaft (haftungsbeschränkt)","OHG","Aktiengesellschaft"],a:1,e:"Die UG (haftungsbeschränkt) ist eine Variante der GmbH. Sie muss einen Teil des Jahresüberschusses in eine gesetzliche Rücklage einstellen, bis das GmbH-Mindestkapital erreicht ist.",l:"GmbHG § 5a",t:"Rechtsform",s:"mittel",p:"Entwurf, Fachprüfung offen"},
 {id:"T3-2-08",hf:"III-2",q:"Was gehört zum klassischen Marketing-Mix (die vier P)?",o:["Produkt, Preis, Platzierung, Promotion","Planung, Personal, Prozess, Profit","Produkt, Personal, Prüfung, Preis","Preis, Prognose, Platz, Politik"],a:0,e:"Die vier Instrumente sind Produkt, Preis, Platzierung (Distribution) und Promotion (Kommunikation).",l:"Marketing-Grundlagen",t:"Marketing",s:"leicht",p:"Entwurf, Fachprüfung offen"},
 {id:"T3-2-09",hf:"III-2",q:"Was stellt ein Liquiditätsplan gegenüber?",o:["Erträge und Aufwendungen","Einzahlungen und Auszahlungen","Aktiva und Passiva","Fixkosten und variable Kosten"],a:1,e:"Der Liquiditätsplan zeigt Zahlungsströme: Einzahlungen und Auszahlungen je Monat. So erkennt man Engpässe früh.",l:"Finanzplanung",t:"Finanzplanung",s:"mittel",p:"Entwurf, Fachprüfung offen"},
 {id:"T3-2-10",hf:"III-2",q:"Welche Maßnahme ist Außenfinanzierung mit Fremdkapital?",o:["Gewinne im Betrieb lassen","Aufnahme eines Bankdarlehens","Einlage des Inhabers aus dem Privatvermögen","Rückfluss von Abschreibungen"],a:1,e:"Ein Bankdarlehen ist Fremdkapital von außen. Eine Einlage des Inhabers ist Eigenkapital von außen. Einbehaltene Gewinne und Abschreibungen sind Innenfinanzierung.",l:"Finanzierung",t:"Finanzierung",s:"mittel",p:"Entwurf, Fachprüfung offen"},
 {id:"T3-2-11",hf:"III-2",q:"Welche Versicherung schützt die Beschäftigten eines Handwerksbetriebs gesetzlich gegen die Folgen von Arbeitsunfällen?",o:["Betriebshaftpflichtversicherung","Gesetzliche Unfallversicherung bei der Berufsgenossenschaft","Rechtsschutzversicherung","Betriebsunterbrechungsversicherung"],a:1,e:"Die gesetzliche Unfallversicherung ist für Unternehmer mit Beschäftigten Pflicht. Die anderen genannten Versicherungen sind freiwillig.",l:"SGB VII",t:"Versicherungen",s:"leicht",p:"Entwurf, Fachprüfung offen"},
 {id:"T3-2-12",hf:"III-2",q:"Wie haften die Gesellschafter einer GbR gegenüber den Gläubigern?",o:["Nur mit ihrer Einlage","Persönlich und unbeschränkt","Nur der Geschäftsführer haftet","Überhaupt nicht"],a:1,e:"Bei der Gesellschaft bürgerlichen Rechts haften die Gesellschafter für Verbindlichkeiten der Gesellschaft persönlich und unbeschränkt.",l:"BGB, GbR-Recht",t:"Rechtsform",s:"mittel",p:"Entwurf, Fachprüfung offen"},
 {id:"T3-2-14",hf:"III-2",q:"Welche Form ist für den Gesellschaftsvertrag einer GmbH vorgeschrieben?",o:["Mündliche Vereinbarung","Einfache Schriftform","Notarielle Beurkundung","Eintragung im Gewerberegister"],a:2,e:"Der Gesellschaftsvertrag muss notariell beurkundet werden. Die GmbH entsteht mit Eintragung im Handelsregister.",l:"GmbHG § 2",t:"Rechtsform",s:"mittel",p:"Entwurf, Fachprüfung offen"},
 {id:"T3-2-16",hf:"III-2",q:"Was versteht man bei der Betriebsübernahme unter einer Due Diligence?",o:["Die Anmeldung beim Gewerbeamt","Die sorgfältige wirtschaftliche, rechtliche und steuerliche Prüfung des Betriebs vor dem Kauf","Die Verhandlung des Kaufpreises","Die Übergabe der Schlüssel"],a:1,e:"Der Käufer prüft den Betrieb vor dem Kauf auf Risiken wie Altschulden, laufende Verträge, offene Streitigkeiten und Steuern.",l:"Unternehmenskauf",t:"Betriebsübernahme",s:"mittel",p:"Entwurf, Fachprüfung offen"},
 {id:"T3-2-17",hf:"III-2",q:"Woran orientiert sich das Ertragswertverfahren?",o:["An den Anschaffungskosten der Maschinen","An den zukünftig erwarteten Erträgen des Betriebs","An der Zahl der Mitarbeiter","Am Umsatz des Vorjahres allein"],a:1,e:"Der Ertragswert ist der Barwert der erwarteten zukünftigen Überschüsse. Der Substanzwert dagegen bewertet das vorhandene Vermögen.",l:"Unternehmensbewertung",t:"Unternehmensbewertung",s:"mittel",p:"Entwurf, Fachprüfung offen"},
 {id:"T3-2-19",hf:"III-2",q:"Was geschieht mit den Arbeitsverhältnissen, wenn ein Betrieb durch Rechtsgeschäft auf einen neuen Inhaber übergeht?",o:["Sie enden automatisch.","Sie gehen mit allen Rechten und Pflichten auf den Erwerber über.","Sie gehen nur über, wenn der Erwerber zustimmt.","Sie gehen nur bei Betrieben über 100 Beschäftigten über."],a:1,e:"Bei einem Betriebsübergang tritt der Erwerber in die bestehenden Arbeitsverhältnisse ein. Die Beschäftigten können dem Übergang widersprechen.",l:"BGB § 613a",t:"Betriebsübergang",s:"schwer",p:"Entwurf, Fachprüfung offen"},
 {id:"T3-2-20",hf:"III-2",q:"Welche Aufgabe hat eine Bürgschaftsbank?",o:["Sie berät bei der Gewerbeanmeldung.","Sie übernimmt Bürgschaften für Kredite, wenn dem Gründer ausreichende Sicherheiten fehlen.","Sie zahlt Gründern einen Zuschuss für die Meisterprüfung.","Sie führt die Handwerksrolle."],a:1,e:"Bürgschaftsbanken sichern Bankkredite ab und erleichtern so die Finanzierung von Gründungen und Übernahmen.",l:"Finanzierung",t:"Finanzierung",s:"mittel",p:"Entwurf, Fachprüfung offen"},
 {id:"T3-2-22",hf:"III-2",q:"Welche Kreditsicherheit wird im Grundbuch eingetragen?",o:["Sicherungsübereignung","Bürgschaft","Grundschuld","Eigentumsvorbehalt"],a:2,e:"Die Grundschuld sichert einen Kredit durch ein Grundstück und wird in Abteilung III des Grundbuchs eingetragen.",l:"BGB § 1191",t:"Kreditsicherheiten",s:"mittel",p:"Entwurf, Fachprüfung offen"},
 {id:"T3-2-24",hf:"III-2",q:"Welche Steuer zahlt eine GmbH auf ihren Gewinn?",o:["Einkommensteuer","Körperschaftsteuer","Erbschaftsteuer","Kfz-Steuer"],a:1,e:"Kapitalgesellschaften sind selbst steuerpflichtig und zahlen Körperschaftsteuer. Einzelunternehmer und Personengesellschafter zahlen Einkommensteuer.",l:"KStG",t:"Steuern",s:"mittel",p:"Entwurf, Fachprüfung offen"},
 {id:"T3-2-25",hf:"III-2",q:"Wer legt den Hebesatz der Gewerbesteuer fest?",o:["Das Finanzamt","Die Gemeinde","Die Handwerkskammer","Das Bundesland"],a:1,e:"Die Gewerbesteuer ist eine Gemeindesteuer. Die Gemeinde bestimmt den Hebesatz, der für den Standort eine Rolle spielt.",l:"GewStG § 16",t:"Steuern",s:"mittel",p:"Entwurf, Fachprüfung offen"},
 {id:"T3-2-26",hf:"III-2",q:"Ein Darlehen über 40.000 € wird mit 5 % verzinst und jährlich mit 4.000 € getilgt. Wie hoch ist der Kapitaldienst im ersten Jahr, wenn die Zinsen auf die Anfangsschuld berechnet werden?",o:["2.000 €","4.000 €","6.000 €","8.000 €"],a:2,e:"Zinsen: 5 % von 40.000 € = 2.000 €. Kapitaldienst = Zinsen + Tilgung = 2.000 € + 4.000 € = 6.000 €.",l:"Finanzierung",t:"Finanzierung",s:"mittel",p:"Rechnung nachgerechnet, Fachprüfung offen"},
 {id:"T3-2-27",hf:"III-2",q:"Wie lange haben Arbeitnehmer nach der Unterrichtung über einen Betriebsübergang Zeit, dem Übergang ihres Arbeitsverhältnisses zu widersprechen?",o:["1 Woche","2 Wochen","1 Monat","3 Monate"],a:2,e:"Der Widerspruch muss schriftlich innerhalb eines Monats nach Zugang der Unterrichtung erklärt werden.",l:"BGB § 613a Abs. 6",t:"Betriebsübergang",s:"mittel",p:"Gesetzestext geprüft"},
 {id:"T3-2-28",hf:"III-2",q:"Was gilt für tarifliche Regelungen, die beim Betriebsübergang Inhalt des Arbeitsverhältnisses werden?",o:["Sie dürfen sofort verschlechtert werden.","Sie dürfen grundsätzlich nicht vor Ablauf eines Jahres zum Nachteil der Arbeitnehmer geändert werden.","Sie entfallen am Tag des Übergangs.","Sie gelten nur für den Veräußerer."],a:1,e:"Regelungen aus Tarifvertrag oder Betriebsvereinbarung werden Inhalt des Arbeitsverhältnisses und dürfen grundsätzlich innerhalb eines Jahres nach dem Übergang nicht zum Nachteil geändert werden.",l:"BGB § 613a Abs. 1",t:"Betriebsübergang",s:"schwer",p:"Gesetzestext geprüft"},
 {id:"T3-2-29",hf:"III-2",q:"Wer kann nach der Handwerksordnung ein zulassungspflichtiges Handwerk selbstständig betreiben, wenn er in der Handwerksrolle eingetragen ist?",o:["Nur natürliche Personen","Natürliche Personen, juristische Personen und Personengesellschaften","Nur Kapitalgesellschaften","Nur Mitglieder der Innung"],a:1,e:"Betreiber können natürliche Personen, juristische Personen und Personengesellschaften sein, sofern die Voraussetzungen für die Eintragung erfüllt sind.",l:"HwO § 1",t:"Handwerksrolle",s:"mittel",p:"Gesetzestext geprüft"},
 {id:"T3-2-30",hf:"III-2",q:"Wann ist ein Gewerbebetrieb grundsätzlich ein Handelsgewerbe und damit eintragungspflichtig?",o:["Immer bei einem Handwerksbetrieb","Wenn er einen in kaufmännischer Weise eingerichteten Geschäftsbetrieb erfordert","Nur bei mehr als einem Mitarbeiter","Nur bei Umsatz über 1 Million €"],a:1,e:"Ein Gewerbebetrieb ist Handelsgewerbe, wenn nach Art und Umfang ein kaufmännisch eingerichteter Geschäftsbetrieb erforderlich ist. Kleingewerbetreibende können sich freiwillig eintragen lassen.",l:"HGB §§ 1, 2",t:"Handelsregister",s:"mittel",p:"Entwurf, Fachprüfung offen"},
 {id:"T3-2-31",hf:"III-2",q:"Wofür steht das AIDA-Modell in der Werbung?",o:["Attention, Interest, Desire, Action","Analyse, Idee, Durchführung, Auswertung","Angebot, Information, Distribution, Absatz","Auftrag, Idee, Design, Abnahme"],a:0,e:"Das Modell beschreibt die Wirkung von Werbung: Aufmerksamkeit, Interesse, Wunsch und Handlung.",l:"Marketing-Grundlagen",t:"Werbung",s:"leicht",p:"Entwurf, Fachprüfung offen"},
 {id:"T3-3-01",hf:"III-3",q:"Was beschreibt die Ablauforganisation?",o:["Die Gliederung in Abteilungen und Stellen","Den zeitlichen und räumlichen Ablauf von Arbeitsprozessen","Die Rechtsform des Betriebs","Die Verteilung von Gewinnen"],a:1,e:"Die Aufbauorganisation legt Stellen, Abteilungen und Weisungswege fest. Die Ablauforganisation regelt, wie und in welcher Reihenfolge Arbeit erledigt wird.",l:"Organisationslehre",t:"Organisation",s:"leicht",p:"Entwurf, Fachprüfung offen"},
 {id:"T3-3-02",hf:"III-3",q:"Ein Arbeitnehmer ist seit 3 Jahren im Betrieb. Der Arbeitgeber kündigt ordentlich, es gibt keine abweichende Vereinbarung. Welche Frist gilt?",o:["2 Wochen","4 Wochen zum 15. oder Monatsende","1 Monat zum Monatsende","2 Monate zum Monatsende"],a:2,e:"Ab 2 Jahren Betriebszugehörigkeit verlängert sich die Kündigungsfrist des Arbeitgebers auf 1 Monat zum Monatsende, ab 5 Jahren auf 2 Monate.",l:"BGB § 622 Abs. 2",t:"Arbeitsrecht",s:"mittel",p:"Quelle belegt"},
 {id:"T3-3-03",hf:"III-3",q:"Wie lang darf die Probezeit in einem Arbeitsverhältnis höchstens sein, und welche Frist gilt in dieser Zeit?",o:["3 Monate, 4 Wochen","6 Monate, 2 Wochen","4 Monate, fristlos","12 Monate, 1 Monat"],a:1,e:"Während einer vereinbarten Probezeit von höchstens 6 Monaten kann mit 2 Wochen Frist gekündigt werden.",l:"BGB § 622 Abs. 3",t:"Arbeitsrecht",s:"mittel",p:"Quelle belegt"},
 {id:"T3-3-04",hf:"III-3",q:"Wie viele Urlaubstage stehen einem Vollzeit-Arbeitnehmer mit einer 5-Tage-Woche gesetzlich mindestens zu?",o:["15 Tage","20 Tage","24 Tage","30 Tage"],a:1,e:"Das Bundesurlaubsgesetz sieht 24 Werktage vor, bezogen auf eine 6-Tage-Woche. Bei einer 5-Tage-Woche sind das 20 Arbeitstage.",l:"BUrlG § 3",t:"Arbeitsrecht",s:"mittel",p:"Quelle belegt"},
 {id:"T3-3-06",hf:"III-3",q:"Ein Betrieb stellt am 10.03.2026 eine Rechnung. Die Forderung entstand 2026, der Betrieb kennt Schuldner und Forderung. Wann verjährt der Anspruch nach der regelmäßigen Verjährungsfrist?",o:["Am 10.03.2029","Am 31.12.2029","Am 31.12.2031","Am 10.03.2036"],a:1,e:"Die regelmäßige Frist beträgt 3 Jahre und beginnt mit dem Schluss des Jahres, in dem der Anspruch entstanden ist: Ende 2026 plus 3 Jahre = 31.12.2029.",l:"BGB § 195, § 199 Abs. 1",t:"Forderungen",s:"mittel",p:"Quelle belegt"},
 {id:"T3-3-07",hf:"III-3",q:"Wie lange verjähren Mängelansprüche bei einem Bauwerk nach dem BGB-Werkvertragsrecht?",o:["2 Jahre ab Abnahme","3 Jahre ab Abnahme","4 Jahre ab Abnahme","5 Jahre ab Abnahme"],a:3,e:"Bei Bauwerken verjähren Mängelansprüche nach BGB in 5 Jahren ab Abnahme.",l:"BGB § 634a Abs. 1 Nr. 2",t:"Gewährleistung",s:"mittel",p:"Quelle belegt"},
 {id:"T3-3-08",hf:"III-3",q:"Welche Frist gilt für Mängelansprüche bei Bauwerken, wenn die VOB/B wirksam vereinbart ist?",o:["2 Jahre","3 Jahre","4 Jahre","5 Jahre"],a:2,e:"Ist nichts anderes vereinbart, beträgt die Frist nach VOB/B bei Bauwerken 4 Jahre.",l:"VOB/B § 13 Abs. 4",t:"Gewährleistung",s:"mittel",p:"Quelle belegt"},
 {id:"T3-3-09",hf:"III-3",q:"Welche Reihenfolge beschreibt den üblichen Weg zur Durchsetzung einer unbestrittenen Geldforderung?",o:["Mahnbescheid, Mahnung, Vollstreckungsbescheid","Mahnung, Mahnbescheid, Vollstreckungsbescheid","Vollstreckungsbescheid, Mahnbescheid, Mahnung","Klage, Mahnbescheid, Mahnung"],a:1,e:"Zuerst mahnt der Gläubiger außergerichtlich. Danach kann er einen Mahnbescheid beantragen und nach Ablauf der Widerspruchsfrist einen Vollstreckungsbescheid.",l:"ZPO § 688 ff.",t:"Forderungen",s:"mittel",p:"Entwurf, Fachprüfung offen"},
 {id:"T3-3-10",hf:"III-3",q:"Der Geschäftsführer einer GmbH stellt fest, dass die GmbH zahlungsunfähig ist. Innerhalb welcher Frist muss er spätestens den Insolvenzantrag stellen?",o:["1 Woche","3 Wochen","6 Wochen","3 Monate"],a:1,e:"Bei Zahlungsunfähigkeit muss der Antrag ohne schuldhaftes Zögern, spätestens nach 3 Wochen gestellt werden. Bei Überschuldung sind es 6 Wochen.",l:"InsO § 15a Abs. 1",t:"Insolvenz",s:"schwer",p:"Quelle belegt"},
 {id:"T3-3-11",hf:"III-3",q:"Was gilt bei drohender Zahlungsunfähigkeit?",o:["Es besteht eine Antragspflicht innerhalb von 3 Wochen.","Es besteht nur ein Antragsrecht, aber keine Antragspflicht.","Es besteht eine Antragspflicht innerhalb von 6 Wochen.","Die Gläubiger müssen sofort einen Insolvenzantrag stellen."],a:1,e:"Die drohende Zahlungsunfähigkeit begründet ein Antragsrecht des Schuldners. Die Antragspflicht entsteht erst bei Zahlungsunfähigkeit oder Überschuldung.",l:"InsO §§ 15a, 18",t:"Insolvenz",s:"schwer",p:"Quelle belegt"},
 {id:"T3-3-12",hf:"III-3",q:"Wie hoch ist der Pflichtteil eines Pflichtteilsberechtigten?",o:["Das volle gesetzliche Erbteil","Die Hälfte des Werts des gesetzlichen Erbteils","Ein Viertel des Nachlasses","Ein Drittel des gesetzlichen Erbteils"],a:1,e:"Der Pflichtteil beträgt die Hälfte des Werts des gesetzlichen Erbteils. Wichtig bei der Betriebsnachfolge.",l:"BGB § 2303 Abs. 1",t:"Nachfolge",s:"mittel",p:"Entwurf, Fachprüfung offen"},
 {id:"T3-3-13",hf:"III-3",q:"Was kennzeichnet den autoritären Führungsstil?",o:["Die Mitarbeiter entscheiden gemeinsam.","Der Vorgesetzte trifft Entscheidungen allein und gibt Anweisungen.","Der Vorgesetzte greift nie ein.","Die Ziele werden gemeinsam vereinbart."],a:1,e:"Beim autoritären Stil entscheidet der Vorgesetzte allein. Beim kooperativen Stil werden Mitarbeiter beteiligt, beim Laissez-faire-Stil gibt es kaum Führung.",l:"Führungslehre",t:"Führungsstile",s:"leicht",p:"Entwurf, Fachprüfung offen"},
 {id:"T3-3-15",hf:"III-3",q:"Wofür steht der PDCA-Zyklus?",o:["Planen, Durchführen, Prüfen, Handeln","Prüfen, Drucken, Ändern, Abnehmen","Preis, Dienstleistung, Kunde, Auftrag","Produkt, Design, Kosten, Absatz"],a:0,e:"Der Zyklus Plan, Do, Check, Act beschreibt die ständige Verbesserung von Abläufen: planen, umsetzen, kontrollieren, anpassen.",l:"Qualitätsmanagement",t:"Qualitätsmanagement",s:"leicht",p:"Entwurf, Fachprüfung offen"},
 {id:"T3-3-16",hf:"III-3",q:"Welche Hauptpflicht hat der Unternehmer im Werkvertrag?",o:["Die Bezahlung des Werkes","Die Herstellung des versprochenen Werkes frei von Mängeln","Die Lieferung ohne Frist","Die Beratung des Bestellers"],a:1,e:"Der Unternehmer schuldet den versprochenen Erfolg, der Besteller die vereinbarte Vergütung.",l:"BGB § 631",t:"Werkvertrag",s:"leicht",p:"Entwurf, Fachprüfung offen"},
 {id:"T3-3-17",hf:"III-3",q:"Welche Folgen hat die Abnahme beim Werkvertrag?",o:["Die Vergütung wird fällig und die Verjährung der Mängelansprüche beginnt.","Der Vertrag endet ohne Zahlung.","Der Unternehmer verliert seine Haftung.","Der Besteller muss erst nach Ablauf der Gewährleistung zahlen."],a:0,e:"Mit der Abnahme wird das Werk als im Wesentlichen vertragsgemäß anerkannt. Die Vergütung wird fällig, die Verjährungsfrist für Mängel beginnt, und die Beweislast geht auf den Besteller über.",l:"BGB §§ 640, 641, 634a",t:"Abnahme",s:"mittel",p:"Entwurf, Fachprüfung offen"},
 {id:"T3-3-18",hf:"III-3",q:"Was bedeutet Eigentumsvorbehalt?",o:["Die Ware gehört sofort dem Käufer.","Die Ware bleibt bis zur vollständigen Bezahlung Eigentum des Verkäufers.","Der Käufer darf die Ware zurückgeben.","Die Ware darf nicht verwendet werden."],a:1,e:"Der Verkäufer bleibt Eigentümer, bis der Kaufpreis vollständig bezahlt ist. Das sichert seine Forderung.",l:"BGB § 449",t:"Kaufrecht",s:"mittel",p:"Entwurf, Fachprüfung offen"},
 {id:"T3-3-19",hf:"III-3",q:"Was gilt für die wesentlichen Arbeitsbedingungen eines Arbeitnehmers?",o:["Sie dürfen nur mündlich vereinbart werden.","Der Arbeitgeber muss sie nachweisen: schriftlich oder in Textform, im Baugewerbe nur schriftlich.","Sie müssen nur auf Verlangen aufgeschrieben werden.","Sie sind im Handelsregister zu veröffentlichen."],a:1,e:"Der Arbeitgeber muss die wesentlichen Vertragsbedingungen nachweisen. Seit 1.1.2025 reicht dafür auch die Textform, z. B. eine E-Mail mit PDF, wenn der Arbeitnehmer das Dokument speichern und ausdrucken kann und den Empfang bestätigt. In bestimmten Branchen, u. a. im Baugewerbe (§ 2a Schwarzarbeitsbekämpfungsgesetz), muss es weiter schriftlich mit Unterschrift sein.",l:"NachwG § 2",t:"Arbeitsrecht",s:"mittel",p:"Entwurf, Fachprüfung offen"},
 {id:"T3-3-20",hf:"III-3",q:"Ab wie vielen ständig wahlberechtigten Arbeitnehmern kann ein Betriebsrat gewählt werden?",o:["Ab 1","Ab 5","Ab 20","Ab 50"],a:1,e:"Betriebsräte werden in Betrieben mit in der Regel mindestens fünf ständigen wahlberechtigten Arbeitnehmern gewählt, von denen drei wählbar sind.",l:"BetrVG § 1",t:"Betriebsverfassung",s:"mittel",p:"Entwurf, Fachprüfung offen"},
 {id:"T3-3-21",hf:"III-3",q:"Wer muss eine Gefährdungsbeurteilung der Arbeitsplätze durchführen?",o:["Der Arbeitnehmer","Der Arbeitgeber","Die Berufsschule","Das Finanzamt"],a:1,e:"Der Arbeitgeber muss Gefährdungen am Arbeitsplatz beurteilen und Schutzmaßnahmen festlegen.",l:"ArbSchG § 5",t:"Arbeitsschutz",s:"mittel",p:"Entwurf, Fachprüfung offen"},
 {id:"T3-3-23",hf:"III-3",q:"Eine Rechnung hat ein kalendermäßig bestimmtes Zahlungsziel (zum Beispiel 30.06.). Der Kunde zahlt nicht. Wann gerät er in Verzug?",o:["Erst nach zwei Mahnungen","Mit Ablauf des Zahlungsziels, auch ohne Mahnung","Erst nach einem Jahr","Nur nach Zustellung eines Mahnbescheids"],a:1,e:"Ist die Leistungszeit nach dem Kalender bestimmt, kommt der Schuldner mit Ablauf dieses Tages in Verzug, ohne dass eine Mahnung nötig ist.",l:"BGB § 286 Abs. 2",t:"Zahlungsverzug",s:"mittel",p:"Entwurf, Fachprüfung offen"},
 {id:"T3-3-24",hf:"III-3",q:"Eine gekaufte Ware hat einen Sachmangel. Was kann der Käufer in der Regel zuerst verlangen?",o:["Rücktritt vom Vertrag","Schadensersatz","Nacherfüllung","Preisminderung"],a:2,e:"Der Käufer muss dem Verkäufer zuerst Gelegenheit zur Nacherfüllung geben, also Reparatur oder Ersatzlieferung. Erst danach kommen Rücktritt oder Minderung in Betracht.",l:"BGB §§ 437, 439",t:"Kaufrecht",s:"mittel",p:"Entwurf, Fachprüfung offen"},
 {id:"T3-3-25",hf:"III-3",q:"Welcher Grund ist kein Eröffnungsgrund für ein Insolvenzverfahren?",o:["Zahlungsunfähigkeit","Überschuldung einer GmbH","Gewinnrückgang","Drohende Zahlungsunfähigkeit auf Antrag des Schuldners"],a:2,e:"Eröffnungsgründe sind Zahlungsunfähigkeit, Überschuldung bei juristischen Personen und drohende Zahlungsunfähigkeit auf Antrag des Schuldners. Ein bloßer Gewinnrückgang ist keiner.",l:"InsO §§ 16 bis 19",t:"Insolvenz",s:"schwer",p:"Entwurf, Fachprüfung offen"},
 {id:"T3-3-27",hf:"III-3",q:"Was wird beim Soll-Ist-Vergleich im Controlling verglichen?",o:["Geplante Werte mit tatsächlich erreichten Werten","Eigene Preise mit Wettbewerberpreisen","Alte Maschinen mit neuen Maschinen","Zwei Bilanzen aus verschiedenen Jahren ohne Plan"],a:0,e:"Der Soll-Ist-Vergleich zeigt Abweichungen zwischen Plan und Realität und ist die Grundlage für Gegenmaßnahmen.",l:"Controlling",t:"Controlling",s:"leicht",p:"Entwurf, Fachprüfung offen"},
 {id:"T3-3-28",hf:"III-3",q:"Was darf ein Prokurist ohne besondere Befugnis nicht?",o:["Verträge im Namen des Betriebs abschließen","Grundstücke veräußern und belasten","Mitarbeiter einstellen","Rechnungen unterschreiben"],a:1,e:"Die Prokura umfasst fast alle Geschäfte des Handelsgewerbes. Für die Veräußerung und Belastung von Grundstücken braucht der Prokurist eine besondere Befugnis.",l:"HGB §§ 49, 50",t:"Vollmachten",s:"schwer",p:"Entwurf, Fachprüfung offen"},
 {id:"T3-3-29",hf:"III-3",q:"Wodurch wird die Verjährung eines Anspruchs gehemmt?",o:["Durch Schweigen des Schuldners","Durch Verhandlungen über den Anspruch","Durch das Ende des Kalenderjahrs","Durch einen Wohnortwechsel"],a:1,e:"Schweben Verhandlungen zwischen Gläubiger und Schuldner, ist die Verjährung gehemmt, bis ein Teil die Fortsetzung verweigert. Danach läuft sie nach kurzer Frist weiter.",l:"BGB § 203",t:"Verjährung",s:"schwer",p:"Entwurf, Fachprüfung offen"},
 {id:"T3-3-31",hf:"III-3",q:"Wie kommt ein Vertrag grundsätzlich zustande?",o:["Durch Angebot und übereinstimmende Annahme","Durch einseitige Erklärung des Verkäufers","Nur durch Unterschrift beim Notar","Nur durch Zahlung"],a:0,e:"Ein Vertrag entsteht durch zwei übereinstimmende Willenserklärungen, Angebot und Annahme. Eine besondere Form ist nur in Ausnahmefällen vorgeschrieben.",l:"BGB §§ 145 ff.",t:"Vertragsschluss",s:"leicht",p:"Entwurf, Fachprüfung offen"},
 {id:"T3-3-32",hf:"III-3",q:"Wie lang ist die Widerrufsfrist bei einem Verbrauchervertrag, der außerhalb von Geschäftsräumen geschlossen wurde, in der Regel?",o:["7 Tage","14 Tage","30 Tage","6 Monate"],a:1,e:"Verbraucher können solche Verträge grundsätzlich innerhalb von 14 Tagen widerrufen. Voraussetzung ist eine ordnungsgemäße Widerrufsbelehrung, sonst verlängert sich die Frist.",l:"BGB §§ 312g, 355",t:"Verbraucherrecht",s:"mittel",p:"Entwurf, Fachprüfung offen"},
 {id:"T3-3-33",hf:"III-3",q:"Nach spätestens wie vielen Tagen nach Fälligkeit und Zugang der Rechnung kommt ein Schuldner einer Entgeltforderung ohne Mahnung in Verzug?",o:["10 Tage","20 Tage","30 Tage","60 Tage"],a:2,e:"Der Schuldner einer Entgeltforderung kommt spätestens 30 Tage nach Fälligkeit und Zugang der Rechnung in Verzug. Gegenüber Verbrauchern gilt das nur, wenn auf die Folgen hingewiesen wurde.",l:"BGB § 286 Abs. 3",t:"Zahlungsverzug",s:"mittel",p:"Entwurf, Fachprüfung offen"},
 {id:"T3-3-34",hf:"III-3",q:"Bis wann muss der Arbeitgeber nach dem Nachweisgesetz Name und Anschrift der Vertragsparteien, das Arbeitsentgelt und die Arbeitszeit nachweisen?",o:["Spätestens am ersten Tag der Arbeitsleistung","Spätestens einen Monat nach Beginn","Spätestens nach der Probezeit","Spätestens nach einem Jahr"],a:0,e:"Diese Angaben müssen spätestens am ersten Tag der Arbeitsleistung nachgewiesen werden, schriftlich oder seit 2025 auch in Textform (nicht im Baugewerbe). Für andere Angaben gelten Fristen von sieben Kalendertagen oder einem Monat.",l:"NachwG § 2",t:"Arbeitsrecht",s:"mittel",p:"Gesetzestext geprüft"},
 {id:"T3-3-35",hf:"III-3",q:"Für welchen Zeitraum prognostiziert man in der Regel, ob Zahlungsunfähigkeit droht?",o:["6 Monate","12 Monate","24 Monate","60 Monate"],a:2,e:"Drohende Zahlungsunfähigkeit liegt vor, wenn der Schuldner voraussichtlich in den nächsten 24 Monaten seine Zahlungspflichten nicht erfüllen kann.",l:"InsO § 18 Abs. 2",t:"Insolvenz",s:"schwer",p:"Gesetzestext geprüft"},
 {id:"T3-3-36",hf:"III-3",q:"Ein Handwerksbetrieb sendet einem Kaufmann nach einem Gespräch eine Zusammenfassung der mündlichen Vereinbarung. Der Kaufmann schweigt. Was ist die rechtliche Folge unter Kaufleuten?",o:["Der Vertrag kommt nie zustande.","Das Schweigen kann als Zustimmung zum Inhalt gelten (kaufmännisches Bestätigungsschreiben).","Der Betrieb muss neu anbieten.","Der Vertrag ist nichtig."],a:1,e:"Unter Kaufleuten gilt Schweigen auf ein kaufmännisches Bestätigungsschreiben in der Regel als Zustimmung zum Inhalt, wenn nicht unverzüglich widersprochen wird.",l:"Handelsbrauch, HGB § 346",t:"Vertragsrecht",s:"schwer",p:"Entwurf, Fachprüfung offen"},
 {id:"T3-3-37",hf:"III-3",q:"Ein Anspruch auf Zahlung entsteht am 05.12.2027, der Gläubiger kennt Schuldner und Anspruch. Wann endet die regelmäßige Verjährungsfrist?",o:["Am 05.12.2030","Am 31.12.2030","Am 31.12.2037","Am 05.12.2037"],a:1,e:"Die regelmäßige Frist beträgt 3 Jahre und beginnt mit dem Schluss des Jahres der Entstehung. Ende: 31.12.2030.",l:"BGB §§ 195, 199",t:"Verjährung",s:"mittel",p:"Gesetzestext geprüft"},
 {id:"T3-3-38",hf:"III-3",q:"In welchen Betrieben werden Betriebsräte gewählt?",o:["In allen Betrieben","In Betrieben mit in der Regel mindestens fünf ständigen wahlberechtigten Arbeitnehmern, von denen drei wählbar sind","Nur in Betrieben mit mehr als 50 Arbeitnehmern","Nur in Industriebetrieben"],a:1,e:"Die Wahl ist ab fünf ständig wahlberechtigten Arbeitnehmern möglich, von denen drei wählbar sind. Sie ist freiwillig, der Arbeitgeber darf sie nicht verhindern.",l:"BetrVG § 1",t:"Betriebsrat",s:"mittel",p:"Gesetzestext geprüft"},
 {id:"T3-3-39",hf:"III-3",q:"Welche Befugnis hat ein Prokurist grundsätzlich nicht ohne besondere Erteilung?",o:["Verträge über Material abschließen","Grundstücke veräußern oder belasten","Rechnungen ausstellen","Angebote unterschreiben"],a:1,e:"Zur Veräußerung und Belastung von Grundstücken ist der Prokurist nur befugt, wenn ihm diese Befugnis besonders erteilt wurde.",l:"HGB § 49 Abs. 2",t:"Vollmacht",s:"mittel",p:"Gesetzestext geprüft"},
 {id:"T4-1-01",hf:"IV-1",q:"Welche Eignung wird vom Ausbildenden und vom Ausbilder verlangt?",o:["Nur fachliche Eignung","Persönliche und fachliche Eignung","Nur ein Meisterbrief","Nur ein Mindestalter von 21 Jahren"],a:1,e:"Der Ausbildende ist der Betrieb bzw. der Inhaber, der den Ausbildungsvertrag schließt. Er muss persönlich geeignet sein. Der Ausbilder ist die Person, die im Betrieb tatsächlich ausbildet. Er muss persönlich und fachlich geeignet sein. Wer selbst nicht fachlich geeignet ist, darf nur ausbilden lassen, wenn er einen geeigneten Ausbilder bestellt.",l:"BBiG § 28, § 29, § 30",t:"Eignung",s:"leicht",p:"Quelle belegt"},
 {id:"T4-1-02",hf:"IV-1",q:"Welche Stelle ist im Handwerk die zuständige Stelle für die Berufsausbildung?",o:["Die Industrie- und Handelskammer","Die Handwerkskammer","Die Agentur für Arbeit","Die Berufsschule"],a:1,e:"Im Handwerk überwacht die Handwerkskammer die Ausbildung, führt das Verzeichnis der Berufsausbildungsverhältnisse und nimmt die Prüfungen ab.",l:"BBiG, HwO",t:"Zuständige Stelle",s:"leicht",p:"Entwurf, Fachprüfung offen"},
 {id:"T4-1-03",hf:"IV-1",q:"Welche Lernorte gehören zum dualen System der Berufsausbildung?",o:["Ausbildungsbetrieb und Berufsschule","Nur der Ausbildungsbetrieb","Hochschule und Betrieb","Nur die Berufsschule"],a:0,e:"Die Ausbildung findet im Betrieb und in der Berufsschule statt. Dazu kommt oft eine überbetriebliche Bildungsstätte als dritter Lernort.",l:"BBiG",t:"Duales System",s:"leicht",p:"Entwurf, Fachprüfung offen"},
 {id:"T4-1-05",hf:"IV-1",q:"Unter welchen Voraussetzungen wird eine Jugend- und Auszubildendenvertretung gewählt?",o:["In jedem Betrieb","In Betrieben mit Betriebsrat und in der Regel mindestens fünf Beschäftigten unter 18 oder Azubis unter 25","Nur in Betrieben mit mehr als 100 Beschäftigten","Auch in Betrieben ohne Betriebsrat"],a:1,e:"Die JAV setzt einen Betriebsrat und in der Regel mindestens fünf Jugendliche oder Auszubildende unter 25 Jahren voraus.",l:"BetrVG § 60 Abs. 1",t:"Interessenvertretung",s:"mittel",p:"Quelle belegt"},
 {id:"T4-1-07",hf:"IV-1",q:"Wonach darf in einem anerkannten Ausbildungsberuf ausgebildet werden?",o:["Nach den Wünschen des Betriebs","Nur nach der Ausbildungsordnung","Nach dem Berufsschullehrplan allein","Nach einem frei gewählten Plan"],a:1,e:"Für anerkannte Ausbildungsberufe darf nur nach der Ausbildungsordnung ausgebildet werden. Sie legt Dauer, Berufsbild und Rahmenplan fest.",l:"BBiG § 4",t:"Ausbildungsordnung",s:"mittel",p:"Entwurf, Fachprüfung offen"},
 {id:"T4-1-09",hf:"IV-1",q:"Zu welcher Kompetenz gehört die Teamfähigkeit?",o:["Fachkompetenz","Sozialkompetenz","Methodenkompetenz","Rechenkompetenz"],a:1,e:"Teamfähigkeit, Kommunikation und Konfliktfähigkeit zählen zur Sozialkompetenz. Handlungskompetenz setzt sich aus Fach-, Sozial- und Selbstkompetenz zusammen. Oft wird auch die Methodenkompetenz genannt: Aufgaben planvoll angehen, Informationen selbst beschaffen und Lerntechniken nutzen.",l:"Berufs- und Arbeitspädagogik",t:"Handlungskompetenz",s:"leicht",p:"Entwurf, Fachprüfung offen"},
 {id:"T4-1-10",hf:"IV-1",q:"Welche Voraussetzung gilt für die Eignung einer Ausbildungsstätte?",o:["Sie muss nach Art und Einrichtung für die Berufsausbildung geeignet sein und die Zahl der Auszubildenden muss in angemessenem Verhältnis zur Zahl der Ausbildungsplätze oder Fachkräfte stehen.","Sie muss mindestens 50 Beschäftigte haben.","Sie muss Mitglied der Innung sein.","Sie muss mindestens zehn Jahre bestehen."],a:0,e:"Auszubildende dürfen nur eingestellt werden, wenn die Ausbildungsstätte geeignet ist und das Zahlenverhältnis passt.",l:"BBiG § 27 Abs. 1",t:"Geeignete Ausbildungsstätte",s:"mittel",p:"Gesetzestext geprüft"},
 {id:"T4-1-11",hf:"IV-1",q:"Ein Betrieb kann nicht alle Ausbildungsinhalte vermitteln. Was gilt?",o:["Er darf nicht ausbilden.","Er gilt als geeignet, wenn die fehlenden Inhalte durch Ausbildungsmaßnahmen außerhalb der Ausbildungsstätte vermittelt werden.","Er muss den Auszubildenden an die Berufsschule abgeben.","Er muss den Ausbildungsberuf wechseln."],a:1,e:"Fehlende Inhalte können in überbetrieblichen Maßnahmen oder im Verbund vermittelt werden. Dann gilt die Ausbildungsstätte als geeignet.",l:"BBiG § 27 Abs. 2",t:"Ausbildungsverbund",s:"mittel",p:"Gesetzestext geprüft"},
 {id:"T4-1-12",hf:"IV-1",q:"Wie viele Handlungsfelder umfasst der schriftliche Teil von Teil IV der Meisterprüfung?",o:["2","3","4","6"],a:2,e:"Der schriftliche Teil gliedert sich in vier Handlungsfelder: 1. Voraussetzungen prüfen und Ausbildung planen, 2. Ausbildung vorbereiten und bei der Einstellung mitwirken, 3. Ausbildung durchführen, 4. Ausbildung abschließen.",l:"AMVO § 4",t:"Handlungsfelder",s:"leicht",p:"Verordnung geprüft"},
 {id:"T4-2-01",hf:"IV-2",q:"Woraus wird der betriebliche Ausbildungsplan abgeleitet?",o:["Aus dem Ausbildungsrahmenplan der Ausbildungsordnung","Aus dem Lehrplan der Berufsschule","Aus dem Arbeitsvertrag","Aus der Gewerbeanmeldung"],a:0,e:"Der Ausbildungsrahmenplan ist Teil der Ausbildungsordnung. Der Betrieb überträgt ihn auf seine Arbeits- und Geschäftsprozesse und erstellt daraus den betrieblichen Plan.",l:"BBiG, Ausbildungsordnung",t:"Ausbildungsplan",s:"mittel",p:"Entwurf, Fachprüfung offen"},
 {id:"T4-2-02",hf:"IV-2",q:"Welches Gesetz verbietet bei der Auswahl von Bewerbern die Benachteiligung wegen Herkunft, Geschlecht oder Alter?",o:["Jugendarbeitsschutzgesetz","Allgemeines Gleichbehandlungsgesetz (AGG)","Handwerksordnung","Bundesurlaubsgesetz"],a:1,e:"Das AGG gilt auch für die Einstellung. Anzeigen und Auswahlverfahren dürfen niemanden aus den genannten Gründen benachteiligen.",l:"AGG",t:"Auswahlverfahren",s:"leicht",p:"Entwurf, Fachprüfung offen"},
 {id:"T4-2-03",hf:"IV-2",q:"Eine 17-jährige Bewerberin soll den Ausbildungsvertrag abschließen. Was ist nötig?",o:["Nichts, die Unterschrift reicht","Die Mitwirkung der gesetzlichen Vertreter","Die Zustimmung der Berufsschule","Die Zustimmung der Innung"],a:1,e:"Minderjährige sind beschränkt geschäftsfähig. Die gesetzlichen Vertreter müssen zustimmen und die Vertragsniederschrift mit unterschreiben.",l:"BGB § 107, BBiG § 11 Abs. 2",t:"Ausbildungsvertrag",s:"leicht",p:"Entwurf, Fachprüfung offen"},
 {id:"T4-2-04",hf:"IV-2",q:"Wann muss der Ausbildende die Niederschrift des Ausbildungsvertrags spätestens aushändigen?",o:["Spätestens vor Beginn der Ausbildung","Nach der Probezeit","Nach einem Jahr","Mit dem Zeugnis"],a:0,e:"Der wesentliche Vertragsinhalt muss in Textform festgehalten und dem Auszubildenden vor Beginn der Ausbildung ausgehändigt werden.",l:"BBiG § 11",t:"Ausbildungsvertrag",s:"mittel",p:"Entwurf, Fachprüfung offen"},
 {id:"T4-2-06",hf:"IV-2",q:"Welche Anforderung gilt für die Ausbildungsvergütung?",o:["Sie muss angemessen sein und mit fortschreitender Ausbildung mindestens jährlich ansteigen.","Sie ist frei verhandelbar, auch ohne Zahlung.","Sie bleibt über die gesamte Ausbildung gleich.","Sie wird von der Berufsschule festgelegt."],a:0,e:"Ausbildende müssen eine angemessene Vergütung zahlen, die nach dem Lebensalter und mit fortschreitender Berufsausbildung mindestens jährlich ansteigt.",l:"BBiG § 17",t:"Vergütung",s:"mittel",p:"Entwurf, Fachprüfung offen"},
 {id:"T4-2-07",hf:"IV-2",q:"Der Betrieb vereinbart im Ausbildungsvertrag, dass der Auszubildende nach Ende der Ausbildung nicht bei einem Wettbewerber arbeiten darf. Wie ist das zu beurteilen?",o:["Zulässig, wenn der Auszubildende zustimmt","Grundsätzlich nichtig","Zulässig für fünf Jahre","Zulässig, wenn die Eltern es wollen"],a:1,e:"Vereinbarungen, die den Auszubildenden für die Zeit nach der Ausbildung in der Ausübung seiner beruflichen Tätigkeit beschränken, sind grundsätzlich nichtig.",l:"BBiG § 12",t:"Ausbildungsvertrag",s:"schwer",p:"Entwurf, Fachprüfung offen"},
 {id:"T4-2-08",hf:"IV-2",q:"Welche Bescheinigung muss für einen Jugendlichen vor Beschäftigungsbeginn vorliegen?",o:["Ein polizeiliches Führungszeugnis","Eine ärztliche Bescheinigung über die Erstuntersuchung","Ein Schulzeugnis","Eine Bescheinigung der Innung"],a:1,e:"Jugendliche dürfen erst beschäftigt werden, wenn sie innerhalb der letzten vierzehn Monate ärztlich untersucht wurden und eine Bescheinigung vorliegt.",l:"JArbSchG § 32",t:"Jugendarbeitsschutz",s:"mittel",p:"Entwurf, Fachprüfung offen"},
 {id:"T4-2-09",hf:"IV-2",q:"In welcher Form muss der wesentliche Inhalt des Ausbildungsvertrags festgehalten werden?",o:["Mündlich reicht aus","In Textform","Nur notariell","Nur handschriftlich"],a:1,e:"Der wesentliche Vertragsinhalt ist unverzüglich nach Abschluss, spätestens vor Beginn der Ausbildung, in Textform festzuhalten.",l:"BBiG § 11 Abs. 1",t:"Ausbildungsvertrag",s:"mittel",p:"Gesetzestext geprüft"},
 {id:"T4-2-10",hf:"IV-2",q:"Was gehört zu den Mindestangaben im Ausbildungsvertrag?",o:["Der Name der Berufsschule und die Unterrichtstage","Die Dauer der Probezeit und die Voraussetzungen für eine Kündigung","Die Schulnoten des Auszubildenden","Die Höhe des Betriebsumsatzes"],a:1,e:"Zu den Mindestangaben zählen unter anderem Beginn und Dauer, Probezeit, Vergütung, Urlaub, Kündigungsvoraussetzungen und die Form des Ausbildungsnachweises.",l:"BBiG § 11",t:"Ausbildungsvertrag",s:"mittel",p:"Gesetzestext geprüft"},
 {id:"T4-2-11",hf:"IV-2",q:"Der Ausbildungsvertrag sieht vor, dass der Auszubildende bei einer Pflichtverletzung eine Vertragsstrafe zahlt. Wie ist das zu bewerten?",o:["Wirksam, wenn die Strafe angemessen ist","Unwirksam","Wirksam nach der Probezeit","Wirksam, wenn die Eltern zustimmen"],a:1,e:"Vereinbarungen über Vertragsstrafen sind in Ausbildungsverträgen unwirksam. Das gilt auch für Entschädigungen für die Ausbildung.",l:"BBiG § 12 Abs. 2",t:"Ausbildungsvertrag",s:"mittel",p:"Gesetzestext geprüft"},
 {id:"T4-2-12",hf:"IV-2",q:"Wo wird der Berufsausbildungsvertrag eingetragen?",o:["Im Handelsregister","Im Verzeichnis der Berufsausbildungsverhältnisse der zuständigen Stelle","Im Grundbuch","Im Gewerbezentralregister"],a:1,e:"Die zuständige Stelle führt das Verzeichnis der Berufsausbildungsverhältnisse. Für Auszubildende ist die Eintragung gebührenfrei.",l:"BBiG § 34",t:"Verzeichnis",s:"leicht",p:"Gesetzestext geprüft"},
 {id:"T4-2-13",hf:"IV-2",q:"Ein nicht tarifgebundener Betrieb zahlt eine Ausbildungsvergütung, die mehr als 20 % unter der einschlägigen tariflichen Vergütung liegt. Wie ist das in der Regel zu beurteilen?",o:["Angemessen","Unangemessen","Zulässig im ersten Ausbildungsjahr","Zulässig mit Zustimmung der Eltern"],a:1,e:"Liegt die Vergütung mehr als 20 % unter dem einschlägigen Tarif, ist sie in der Regel nicht angemessen. Außerdem gilt eine gesetzliche Mindestvergütung.",l:"BBiG § 17",t:"Vergütung",s:"schwer",p:"Gesetzestext geprüft"},
 {id:"T4-3-01",hf:"IV-3",q:"Wie lang muss die Probezeit in der Berufsausbildung sein?",o:["Mindestens 1 Monat und höchstens 4 Monate","Mindestens 3 Monate und höchstens 6 Monate","Genau 3 Monate","Mindestens 2 Wochen und höchstens 2 Monate"],a:0,e:"Die Probezeit in der Ausbildung muss mindestens einen Monat und darf höchstens vier Monate betragen.",l:"BBiG § 20",t:"Probezeit",s:"leicht",p:"Quelle belegt"},
 {id:"T4-3-02",hf:"IV-3",q:"Wie kann das Ausbildungsverhältnis in der Probezeit gekündigt werden?",o:["Mit 4 Wochen Frist und Begründung","Jederzeit ohne Frist, schriftlich","Nur aus wichtigem Grund","Mündlich mit 2 Wochen Frist"],a:1,e:"In der Probezeit können beide Seiten jederzeit ohne Frist kündigen. Die Kündigung muss schriftlich sein.",l:"BBiG § 22 Abs. 1 und 3",t:"Kündigung",s:"mittel",p:"Quelle belegt"},
 {id:"T4-3-03",hf:"IV-3",q:"Nach der Probezeit will ein Auszubildender die Ausbildung aufgeben, um in einem anderen Beruf zu arbeiten. Wie kann er kündigen?",o:["Fristlos ohne Begründung","Mit 4 Wochen Frist, schriftlich mit Angabe der Gründe","Mit 2 Wochen Frist, mündlich","Gar nicht"],a:1,e:"Wer die Ausbildung aufgeben oder einen anderen Beruf erlernen will, kann mit 4 Wochen Frist kündigen, schriftlich und mit Angabe der Gründe.",l:"BBiG § 22 Abs. 2 Nr. 2 und Abs. 3",t:"Kündigung",s:"mittel",p:"Quelle belegt"},
 {id:"T4-3-04",hf:"IV-3",q:"Ein Ausbildender erfährt von einem schweren Pflichtverstoß des Auszubildenden und will aus wichtigem Grund kündigen. Wann ist die Kündigung unwirksam?",o:["Wenn die Tatsachen ihm länger als 2 Wochen bekannt sind","Wenn die Tatsachen ihm länger als 6 Monate bekannt sind","Wenn die Tatsachen ihm länger als 4 Wochen bekannt sind","Wenn die Tatsachen ihm länger als 12 Monate bekannt sind"],a:0,e:"Eine Kündigung aus wichtigem Grund ist unwirksam, wenn die zugrunde liegenden Tatsachen länger als zwei Wochen bekannt sind.",l:"BBiG § 22 Abs. 4",t:"Kündigung",s:"schwer",p:"Quelle belegt"},
 {id:"T4-3-06",hf:"IV-3",q:"Eine Auszubildende ist schwanger und noch in der Probezeit. Kann der Betrieb ohne Weiteres kündigen?",o:["Ja, in der Probezeit immer","Nein, der besondere Kündigungsschutz gilt auch in der Probezeit","Ja, wenn sie zustimmt","Ja, aber nur mit 4 Wochen Frist"],a:1,e:"Das Kündigungsverbot im Mutterschutz gilt ab Beginn der Schwangerschaft, auch in der Probezeit.",l:"MuSchG § 17",t:"Kündigung",s:"schwer",p:"Quelle belegt"},
 {id:"T4-3-07",hf:"IV-3",q:"Welches Lernziel gehört in den psychomotorischen Bereich?",o:["Ein Gesetz nennen können","Eine Schweißnaht fehlerfrei ausführen","Pünktlichkeit als wichtig ansehen","Eine Formel erklären können"],a:1,e:"Psychomotorische Lernziele betreffen Fertigkeiten und Bewegungsabläufe. Kognitive betreffen Wissen, affektive Einstellungen und Werte.",l:"Berufs- und Arbeitspädagogik",t:"Lernziele",s:"mittel",p:"Entwurf, Fachprüfung offen"},
 {id:"T4-3-08",hf:"IV-3",q:"Welche Reihenfolge entspricht der Vier-Stufen-Methode der Unterweisung?",o:["Üben, Vormachen, Vorbereiten, Nachmachen","Vorbereiten, Vormachen und erklären, Nachmachen lassen, Selbstständig üben lassen","Nachmachen, Vorbereiten, Üben, Vormachen","Vormachen, Üben, Nachmachen, Vorbereiten"],a:1,e:"1. Vorbereiten, 2. Vormachen und erklären, 3. Nachmachen und erklären lassen, 4. Selbstständig üben lassen.",l:"Ausbildungsmethodik",t:"Methoden",s:"mittel",p:"Entwurf, Fachprüfung offen"},
 {id:"T4-3-09",hf:"IV-3",q:"Ein Ausbilder beurteilt einen pünktlichen Auszubildenden auch bei Fachwissen und Sorgfalt zu gut, weil ihn die Pünktlichkeit überstrahlt. Wie heißt dieser Beurteilungsfehler?",o:["Halo-Effekt","Tendenz zur Mitte","Mildefehler","Reihenfolgeeffekt"],a:0,e:"Beim Halo-Effekt überstrahlt ein auffälliges Merkmal die Beurteilung anderer Merkmale.",l:"Berufs- und Arbeitspädagogik",t:"Beurteilung",s:"mittel",p:"Entwurf, Fachprüfung offen"},
 {id:"T4-3-11",hf:"IV-3",q:"Wie lange dürfen Jugendliche unter 18 Jahren am Tag höchstens beschäftigt werden?",o:["6 Stunden","8 Stunden","9 Stunden","10 Stunden"],a:1,e:"Jugendliche dürfen nicht mehr als 8 Stunden täglich beschäftigt werden. Es gibt enge Ausnahmen.",l:"JArbSchG § 8",t:"Jugendarbeitsschutz",s:"mittel",p:"Quelle belegt"},
 {id:"T4-3-12",hf:"IV-3",q:"Für welchen Berufsschulunterricht muss der Betrieb einen Auszubildenden freistellen?",o:["Nur für Blockunterricht von mindestens 25 Stunden pro Woche","Für jeden Berufsschulunterricht, auch wenn er nur wenige Stunden dauert","Nur für Berufsschultage mit mehr als fünf Unterrichtsstunden","Nur für Auszubildende unter 18 Jahren"],a:1,e:"Der Betrieb muss Auszubildende für jeden Berufsschulunterricht freistellen, egal wie lang er ist. Die Regel „mehr als fünf Unterrichtsstunden“ bzw. „Blockunterricht ab 25 Stunden“ sagt etwas anderes: An so einem Tag (einmal pro Woche) bzw. in so einer Woche muss der Azubi danach nicht mehr in den Betrieb. Das gilt seit 2020 für alle Azubis, egal wie alt.",l:"BBiG § 15, JArbSchG § 9",t:"Berufsschule",s:"mittel",p:"Quelle belegt"},
 {id:"T4-3-13",hf:"IV-3",q:"Wer kann die Verkürzung der Ausbildungsdauer bei der zuständigen Stelle beantragen?",o:["Nur die Eltern","Nur die Berufsschule","Auszubildende und Ausbildende gemeinsam","Nur die Innung"],a:2,e:"Auf gemeinsamen Antrag von Auszubildenden und Ausbildenden kann die zuständige Stelle die Ausbildungsdauer verkürzen, wenn ein erfolgreicher Abschluss zu erwarten ist.",l:"BBiG § 8 Abs. 1",t:"Verkürzung",s:"mittel",p:"Entwurf, Fachprüfung offen"},
 {id:"T4-3-14",hf:"IV-3",q:"Wie lang muss die Ruhepause für Jugendliche bei einer Arbeitszeit von mehr als sechs Stunden mindestens sein?",o:["15 Minuten","30 Minuten","60 Minuten","90 Minuten"],a:2,e:"Jugendlichen stehen bei mehr als sechs Stunden Arbeitszeit mindestens 60 Minuten Ruhepause zu, bei mehr als viereinhalb bis sechs Stunden mindestens 30 Minuten.",l:"JArbSchG § 11",t:"Jugendarbeitsschutz",s:"mittel",p:"Entwurf, Fachprüfung offen"},
 {id:"T4-3-15",hf:"IV-3",q:"Wie viele Stunden Freizeit müssen Jugendliche nach Arbeitsende bis zum Beginn der nächsten Arbeit mindestens haben?",o:["8 Stunden","10 Stunden","12 Stunden","14 Stunden"],a:2,e:"Nach Beendigung der täglichen Arbeitszeit muss eine ununterbrochene Freizeit von mindestens 12 Stunden liegen.",l:"JArbSchG § 13",t:"Jugendarbeitsschutz",s:"mittel",p:"Entwurf, Fachprüfung offen"},
 {id:"T4-3-16",hf:"IV-3",q:"Wie viele Stunden pro Woche dürfen Jugendliche in der Regel höchstens beschäftigt werden?",o:["35 Stunden","40 Stunden","44 Stunden","48 Stunden"],a:1,e:"Die Wochenarbeitszeit beträgt höchstens 40 Stunden, in der Regel an fünf Tagen in der Woche.",l:"JArbSchG §§ 8, 15",t:"Jugendarbeitsschutz",s:"mittel",p:"Entwurf, Fachprüfung offen"},
 {id:"T4-3-17",hf:"IV-3",q:"Wie viele Werktage Urlaub steht einem noch nicht 16-jährigen Jugendlichen mindestens zu?",o:["20 Werktage","24 Werktage","27 Werktage","30 Werktage"],a:3,e:"Der Urlaub beträgt mindestens 30 Werktage, wenn der Jugendliche zu Beginn des Kalenderjahres noch nicht 16 Jahre alt ist, 27 Werktage bei unter 17 und 25 Werktage bei unter 18.",l:"JArbSchG § 19",t:"Jugendarbeitsschutz",s:"schwer",p:"Entwurf, Fachprüfung offen"},
 {id:"T4-3-18",hf:"IV-3",q:"Wer führt den Ausbildungsnachweis (Berichtsheft)?",o:["Der Ausbilder","Der Auszubildende","Die Berufsschule","Die Handwerkskammer"],a:1,e:"Auszubildende führen den schriftlichen oder elektronischen Ausbildungsnachweis, Ausbildende sehen ihn regelmäßig durch. Zur Prüfung muss er vorgelegt werden.",l:"BBiG §§ 13, 14",t:"Ausbildungsnachweis",s:"leicht",p:"Entwurf, Fachprüfung offen"},
 {id:"T4-3-19",hf:"IV-3",q:"Wer trägt die Kosten für Ausbildungsmittel wie Werkzeug und Werkstoffe, die zur Ausbildung und Prüfung erforderlich sind?",o:["Der Auszubildende","Die Eltern","Der Ausbildende","Die Berufsschule"],a:2,e:"Der Ausbildende hat die Ausbildungsmittel kostenlos zur Verfügung zu stellen, die für die Berufsausbildung und die Prüfungen erforderlich sind.",l:"BBiG § 14",t:"Pflichten",s:"mittel",p:"Entwurf, Fachprüfung offen"},
 {id:"T4-3-21",hf:"IV-3",q:"Welche Funktion hat eine Abmahnung?",o:["Rüge- und Warnfunktion","Nur Belohnung","Nur Beendigung des Vertrags","Verlängerung der Ausbildung"],a:0,e:"Mit der Abmahnung wird ein Fehlverhalten gerügt und für den Wiederholungsfall die Kündigung angedroht. Sie dient auch der Dokumentation.",l:"Arbeitsrecht",t:"Abmahnung",s:"mittel",p:"Entwurf, Fachprüfung offen"},
 {id:"T4-3-22",hf:"IV-3",q:"Welches Lernziel ist ein kognitives Lernziel?",o:["Die Unterschiede zwischen zwei Putzarten benennen können","Eine Wand sauber verputzen können","Sorgfalt im Umgang mit Kundeneigentum zeigen","Pünktlichkeit als Wert annehmen"],a:0,e:"Kognitive Lernziele betreffen Wissen und Verstehen. Praktische Fertigkeiten sind psychomotorisch, Haltungen und Werte affektiv.",l:"Berufs- und Arbeitspädagogik",t:"Lernziele",s:"mittel",p:"Entwurf, Fachprüfung offen"},
 {id:"T4-3-24",hf:"IV-3",q:"Was kennzeichnet die Leittextmethode?",o:["Der Ausbilder erklärt alles mündlich.","Auszubildende erarbeiten eine Aufgabe selbstständig anhand von Leitfragen.","Es wird nur auswendig gelernt.","Der Auszubildende arbeitet nur zu."],a:1,e:"Bei der Leittextmethode planen Auszubildende die Aufgabe selbst, führen sie aus und kontrollieren sie, weitgehend selbstständig anhand von Leitfragen und Arbeitsunterlagen.",l:"Berufs- und Arbeitspädagogik",t:"Methoden",s:"mittel",p:"Entwurf, Fachprüfung offen"},
 {id:"T4-3-25",hf:"IV-3",q:"Welche Regel gilt für konstruktives Feedback?",o:["Verhalten konkret beschreiben, statt die Person zu bewerten","Möglichst allgemein bleiben","Vor der Gruppe kritisieren","Nur Fehler nennen"],a:0,e:"Gutes Feedback beschreibt beobachtbares Verhalten, ist zeitnah, sachlich und wird unter vier Augen gegeben.",l:"Berufs- und Arbeitspädagogik",t:"Feedback",s:"leicht",p:"Entwurf, Fachprüfung offen"},
 {id:"T4-3-28",hf:"IV-3",q:"Ein Ausbilder beurteilt alle Auszubildenden grundsätzlich zu schlecht. Wie heißt dieser Beurteilungsfehler?",o:["Mildefehler","Halo-Effekt","Strengefehler","Tendenz zur Mitte"],a:2,e:"Beim Strengefehler wird zu kritisch beurteilt, beim Mildefehler zu wohlwollend.",l:"Berufs- und Arbeitspädagogik",t:"Beurteilung",s:"mittel",p:"Entwurf, Fachprüfung offen"},
 {id:"T4-3-29",hf:"IV-3",q:"Ein Auszubildender arbeitet über die vereinbarte tägliche Ausbildungszeit hinaus. Was gilt?",o:["Das ist unentgeltlich.","Die Mehrarbeit ist besonders zu vergüten oder durch entsprechende Freizeit auszugleichen.","Sie verfällt nach der Probezeit.","Sie wird auf den Urlaub angerechnet."],a:1,e:"Mehrarbeit ist besonders zu vergüten oder durch Freizeit auszugleichen. Bei Jugendlichen sind zusätzlich die Höchstgrenzen des Jugendarbeitsschutzes zu beachten.",l:"BBiG § 17 Abs. 7",t:"Mehrarbeit",s:"mittel",p:"Gesetzestext geprüft"},
 {id:"T4-3-30",hf:"IV-3",q:"Welche Aufgaben dürfen Auszubildenden übertragen werden?",o:["Alle Aufgaben des Betriebs","Nur Aufgaben, die dem Ausbildungszweck dienen und ihren körperlichen Kräften angemessen sind","Nur Reinigungsarbeiten","Nur Aufgaben nach Wunsch des Auszubildenden"],a:1,e:"Auszubildenden dürfen nur Aufgaben übertragen werden, die dem Ausbildungszweck dienen und ihren körperlichen Kräften angemessen sind.",l:"BBiG § 14 Abs. 3",t:"Pflichten",s:"leicht",p:"Gesetzestext geprüft"},
 {id:"T4-3-31",hf:"IV-3",q:"Wie lang muss eine Ruhepause für Jugendliche mindestens am Stück sein, damit sie als Ruhepause gilt?",o:["5 Minuten","10 Minuten","15 Minuten","30 Minuten"],a:2,e:"Als Ruhepause gilt nur eine Arbeitsunterbrechung von mindestens 15 Minuten.",l:"JArbSchG § 11",t:"Jugendarbeitsschutz",s:"mittel",p:"Gesetzestext geprüft"},
 {id:"T4-3-32",hf:"IV-3",q:"An wie vielen Tagen in der Woche dürfen Jugendliche grundsätzlich beschäftigt werden?",o:["An 4 Tagen","An 5 Tagen","An 6 Tagen","An 7 Tagen"],a:1,e:"Jugendliche dürfen grundsätzlich nur an fünf Tagen in der Woche beschäftigt werden. Ausnahmen bestehen für einzelne Branchen.",l:"JArbSchG § 15",t:"Jugendarbeitsschutz",s:"mittel",p:"Entwurf, Fachprüfung offen"},
 {id:"T4-3-33",hf:"IV-3",q:"Welche Bedürfnisse müssen nach Maslow zuerst erfüllt sein?",o:["Selbstverwirklichung","Grundbedürfnisse wie Essen, Schlaf und Sicherheit","Soziale Anerkennung","Karrierewünsche"],a:1,e:"In Maslows Bedürfnispyramide stehen körperliche Grundbedürfnisse und Sicherheit am Anfang. Erst danach folgen soziale Bedürfnisse, Anerkennung und Selbstverwirklichung.",l:"Berufs- und Arbeitspädagogik",t:"Motivation",s:"leicht",p:"Entwurf, Fachprüfung offen"},
 {id:"T4-3-34",hf:"IV-3",q:"Wie heißen die Phasen der Teamentwicklung nach Tuckman?",o:["Forming, Storming, Norming, Performing","Planning, Doing, Checking, Acting","Reading, Writing, Listening, Speaking","Forming, Norming, Storming, Performing"],a:0,e:"Teams durchlaufen nacheinander Kennenlernen (Forming), Konflikt (Storming), Regelfindung (Norming) und Leistungsphase (Performing). Merke: Erst wird gestritten, dann werden Regeln gefunden.",l:"Berufs- und Arbeitspädagogik",t:"Gruppenarbeit",s:"mittel",p:"Entwurf, Fachprüfung offen"},
 {id:"T4-3-35",hf:"IV-3",q:"Was bedeutet das Gütekriterium Objektivität bei einer Lernerfolgskontrolle?",o:["Das Ergebnis hängt nicht von der Person ab, die auswertet","Die Kontrolle ist schnell und ohne viel Aufwand durchführbar","Die Kontrolle misst genau das Gewünschte","Die Kontrolle ist wiederholbar"],a:0,e:"Objektivität heißt Unabhängigkeit vom Auswerter. Validität bedeutet, dass wirklich das Gewünschte gemessen wird, Reliabilität die Genauigkeit und Wiederholbarkeit.",l:"Berufs- und Arbeitspädagogik",t:"Lernerfolgskontrolle",s:"mittel",p:"Entwurf, Fachprüfung offen"},
 {id:"T4-3-36",hf:"IV-3",q:"Dürfen Jugendliche grundsätzlich sonntags beschäftigt werden?",o:["Ja, immer","Nein, es gilt grundsätzlich ein Beschäftigungsverbot mit Ausnahmen für bestimmte Branchen","Ja, wenn die Eltern zustimmen","Ja, wenn sie dafür an einem anderen Tag frei bekommen"],a:1,e:"An Sonntagen gilt für Jugendliche grundsätzlich ein Beschäftigungsverbot. Ausnahmen bestehen etwa im Gaststätten- und Schaustellergewerbe.",l:"JArbSchG § 17",t:"Sonntagsarbeit",s:"mittel",p:"Entwurf, Fachprüfung offen"},
 {id:"T4-4-01",hf:"IV-4",q:"Ein Auszubildender besteht die Abschlussprüfung nicht. Was gilt für das Ausbildungsverhältnis?",o:["Es endet sofort.","Es verlängert sich auf sein Verlangen bis zur nächsten Wiederholungsprüfung, höchstens um 1 Jahr.","Es verlängert sich automatisch um 2 Jahre.","Es verlängert sich nur mit Zustimmung des Betriebs."],a:1,e:"Besteht der Auszubildende die Abschlussprüfung nicht, verlängert sich das Verhältnis auf sein Verlangen bis zur nächstmöglichen Wiederholungsprüfung, höchstens um ein Jahr.",l:"BBiG § 21 Abs. 3",t:"Wiederholungsprüfung",s:"mittel",p:"Quelle belegt"},
 {id:"T4-4-02",hf:"IV-4",q:"Ein Auszubildender arbeitet nach der bestandenen Prüfung im Betrieb weiter, ohne dass etwas vereinbart wurde. Was entsteht?",o:["Ein befristetes Arbeitsverhältnis über 6 Monate","Ein Arbeitsverhältnis auf unbestimmte Zeit","Ein neues Ausbildungsverhältnis","Gar nichts"],a:1,e:"Wird der Auszubildende nach der Ausbildung ohne Vereinbarung weiterbeschäftigt, gilt ein Arbeitsverhältnis auf unbestimmte Zeit als begründet.",l:"BBiG § 24",t:"Übernahme",s:"mittel",p:"Quelle belegt"},
 {id:"T4-4-03",hf:"IV-4",q:"Was gilt für das Ausbildungszeugnis?",o:["Es gibt keinen Anspruch darauf.","Der Auszubildende hat Anspruch auf ein Zeugnis, auf Verlangen auch mit Angaben zu Führung, Leistung und Fähigkeiten.","Das Zeugnis erstellt die Berufsschule.","Das Zeugnis darf nur mündlich erteilt werden."],a:1,e:"Zum Ende der Ausbildung ist ein schriftliches Zeugnis auszustellen. Auf Verlangen sind Angaben zu Führung, Leistung und besonderen fachlichen Fähigkeiten aufzunehmen.",l:"BBiG § 16",t:"Zeugnis",s:"leicht",p:"Entwurf, Fachprüfung offen"},
 {id:"T4-4-04",hf:"IV-4",q:"Wann endet das Ausbildungsverhältnis, wenn der Auszubildende die Abschlussprüfung vor Ablauf der vereinbarten Zeit besteht?",o:["Erst mit Ablauf der vereinbarten Ausbildungsdauer","Mit der Bekanntgabe des Prüfungsergebnisses","Nach sechs Monaten","Nach der Übernahme"],a:1,e:"Besteht der Auszubildende die Abschlussprüfung vor Ablauf der Ausbildungszeit, endet das Ausbildungsverhältnis mit der Bekanntgabe des Ergebnisses durch den Prüfungsausschuss.",l:"BBiG § 21 Abs. 2",t:"Ende des Ausbildungsverhältnisses",s:"mittel",p:"Entwurf, Fachprüfung offen"},
 {id:"T4-4-05",hf:"IV-4",q:"Wie setzt sich ein Prüfungsausschuss für Abschlussprüfungen zusammen?",o:["Nur aus Arbeitgebern","Aus Beauftragten der Arbeitgeber und der Arbeitnehmer in gleicher Zahl sowie mindestens einer Lehrkraft einer berufsbildenden Schule","Nur aus Lehrern","Nur aus Beamten der Handwerkskammer"],a:1,e:"Der Prüfungsausschuss besteht aus mindestens drei Mitgliedern. Arbeitgeber und Arbeitnehmer sind in gleicher Zahl vertreten, dazu kommt mindestens eine Lehrkraft.",l:"BBiG § 40",t:"Prüfungsausschuss",s:"schwer",p:"Entwurf, Fachprüfung offen"},
 {id:"T4-4-06",hf:"IV-4",q:"Wer errichtet im Handwerk die Prüfungsausschüsse für die Gesellenprüfung?",o:["Die Berufsschule","Die Handwerkskammer beziehungsweise die Innung","Die Agentur für Arbeit","Das Amtsgericht"],a:1,e:"Im Handwerk errichtet die Handwerkskammer Gesellenprüfungsausschüsse oder überträgt dies den Handwerksinnungen.",l:"HwO § 33",t:"Gesellenprüfung",s:"schwer",p:"Entwurf, Fachprüfung offen"},
 {id:"T4-4-07",hf:"IV-4",q:"Wann endet das Ausbildungsverhältnis, wenn die Abschlussprüfung nicht vor Ablauf der Ausbildungszeit bestanden wird?",o:["Mit Ablauf der Ausbildungszeit","Nach der Berufsschule","Nach drei Monaten","Nach Kündigung durch den Ausbildenden"],a:0,e:"Das Ausbildungsverhältnis endet mit Ablauf der Ausbildungszeit. Besteht der Auszubildende die Prüfung nicht, kann er die Verlängerung bis zur Wiederholungsprüfung verlangen, höchstens um ein Jahr.",l:"BBiG § 21",t:"Ende der Ausbildung",s:"mittel",p:"Gesetzestext geprüft"},
 {id:"T4-4-08",hf:"IV-4",q:"Wie viele Mitglieder hat ein Prüfungsausschuss mindestens?",o:["1","2","3","5"],a:2,e:"Der Prüfungsausschuss hat mindestens drei Mitglieder, die fachlich sachkundig und für die Prüfungstätigkeit geeignet sein müssen.",l:"BBiG § 40 Abs. 1",t:"Prüfungsausschuss",s:"leicht",p:"Gesetzestext geprüft"},
 {id:"T4-4-09",hf:"IV-4",q:"Für welchen Zeitraum werden Mitglieder des Prüfungsausschusses höchstens berufen?",o:["1 Jahr","3 Jahre","5 Jahre","10 Jahre"],a:2,e:"Die zuständige Stelle beruft die Mitglieder für längstens fünf Jahre.",l:"BBiG § 40 Abs. 3",t:"Prüfungsausschuss",s:"mittel",p:"Gesetzestext geprüft"},
 {id:"T4-4-10",hf:"IV-4",q:"Wie ist die Tätigkeit im Prüfungsausschuss geregelt?",o:["Sie ist ehrenamtlich, Auslagen und Zeitversäumnis werden entschädigt.","Sie wird wie ein Arbeitsverhältnis bezahlt.","Sie ist unentgeltlich ohne Entschädigung.","Sie ist freiwillig und muss nicht freigestellt werden."],a:0,e:"Die Mitwirkung ist ehrenamtlich. Auslagen und Zeitversäumnis werden entschädigt, und Arbeitgeber müssen Prüfende freistellen, wenn keine wichtigen betrieblichen Gründe entgegenstehen.",l:"BBiG § 40 Abs. 6, 6a",t:"Prüfungsausschuss",s:"mittel",p:"Gesetzestext geprüft"},
 {id:"T4-4-11",hf:"IV-4",q:"Wer richtet im Handwerk grundsätzlich die Gesellenprüfungsausschüsse ein?",o:["Die Handwerkskammer","Die Berufsschule","Das Land","Die Agentur für Arbeit"],a:0,e:"Die Handwerkskammer errichtet die Prüfungsausschüsse. Sie kann Innungen ermächtigen, eigene Ausschüsse zu errichten.",l:"HwO § 33",t:"Gesellenprüfung",s:"mittel",p:"Gesetzestext geprüft"},
 {id:"T4-P-01",hf:"IV-P",q:"Wozu dient das Fachgespräch im praktischen Teil der Prüfung in Teil IV?",o:["Zur Abfrage von Gesetzestexten","Zur Erläuterung der Auswahl und Gestaltung der Ausbildungssituation","Zur Bewertung der Berufsschulnoten","Zur Prüfung der Fachpraxis des Meisterberufs"],a:1,e:"Der Prüfling wählt eine berufstypische Ausbildungssituation aus und führt sie als Präsentation oder praktisch vor. Im Fachgespräch erläutert er Auswahl und Gestaltung.",l:"AMVO § 4 Abs. 4",t:"Fachgespräch",s:"mittel",p:"Quelle belegt"},
 /* Neu am 18.10.2026: eigene Fragen zu Themen aus dem Rahmenplan der AEVO und den Gesetzen (siehe Lektorat.md, Abschnitt 5) */
 {id:"T4-1-13",hf:"IV-1",q:"Wie lange soll eine Berufsausbildung laut Gesetz in der Regel dauern?",o:["Mindestens 1 und höchstens 2 Jahre","Mindestens 2 und höchstens 3 Jahre","Genau 3,5 Jahre","Das legt jeder Betrieb selbst fest"],a:1,e:"Die Ausbildungsordnung legt die Dauer fest. Sie soll nicht mehr als drei und nicht weniger als zwei Jahre betragen. Einige Berufe dauern trotzdem 3,5 Jahre.",l:"BBiG § 5 Abs. 1 Nr. 2",t:"Ausbildungsdauer",s:"leicht",p:"Entwurf, Fachprüfung offen"},
 {id:"T4-1-14",hf:"IV-1",q:"Eine Bewerberin möchte die Ausbildung in Teilzeit machen, weil sie ein kleines Kind betreut. Was gilt?",o:["Teilzeit ist in der Berufsausbildung grundsätzlich nicht erlaubt.","Teilzeit geht nur, wenn die Berufsschule und die Kammer zustimmen.","Teilzeit kann vereinbart werden, die Zeit wird um höchstens die Hälfte gekürzt.","Teilzeit geht nur, wenn die Ausbildung dadurch nicht länger dauert."],a:2,e:"Teilzeit ist erlaubt, wenn Betrieb und Azubi das vereinbaren. Die tägliche oder wöchentliche Zeit darf um höchstens 50 % gekürzt werden. Die Ausbildung dauert dann entsprechend länger.",l:"BBiG § 7a",t:"Teilzeitausbildung",s:"mittel",p:"Entwurf, Fachprüfung offen"},
 {id:"T4-1-15",hf:"IV-1",q:"Wer legt fest, was in der Berufsschule unterrichtet wird (Rahmenlehrplan)?",o:["Die Handwerkskammer des Bezirks","Jeder Ausbildungsbetrieb selbst","Die Kultusministerkonferenz der Länder","Die Agentur für Arbeit vor Ort"],a:2,e:"Für die Berufsschule gilt der Rahmenlehrplan der Kultusministerkonferenz (KMK). Für den Betrieb gilt der Ausbildungsrahmenplan aus der Ausbildungsordnung. Beide sind aufeinander abgestimmt.",l:"Schulrecht der Länder",t:"Duales System",s:"mittel",p:"Entwurf, Fachprüfung offen"},
 {id:"T4-1-16",hf:"IV-1",q:"Wer erlässt die Ausbildungsordnung für einen Handwerksberuf?",o:["Die Handwerkskammer per Satzung","Das Bundesministerium per Rechtsverordnung","Die Innung per Beschluss der Mitglieder","Der Bundestag als eigenes Gesetz"],a:1,e:"Ausbildungsordnungen sind Rechtsverordnungen des Bundes. Im Handwerk erlässt sie das Bundeswirtschaftsministerium im Einvernehmen mit dem Bildungsministerium.",l:"HwO § 25, BBiG § 4",t:"Ausbildungsordnung",s:"mittel",p:"Entwurf, Fachprüfung offen"},
 {id:"T4-1-17",hf:"IV-1",q:"Was steht in der Ausbildungsordnung?",o:["Höhe der Ausbildungsvergütung und Urlaubsanspruch im Betrieb","Noten, Stundenplan und Lehrer der Berufsschule","Arbeitszeiten, Pausen und Urlaubsplan des Betriebs","Dauer, Berufsbild, Ausbildungsrahmenplan und Prüfungsanforderungen"],a:3,e:"Die Ausbildungsordnung regelt mindestens Bezeichnung des Berufs, Dauer, Ausbildungsberufsbild, Ausbildungsrahmenplan und Prüfungsanforderungen. Die Vergütung steht im Ausbildungsvertrag oder Tarifvertrag.",l:"HwO § 26, BBiG § 5",t:"Ausbildungsordnung",s:"leicht",p:"Entwurf, Fachprüfung offen"},
 {id:"T4-1-18",hf:"IV-1",q:"Wer berät und überwacht im Handwerk die Ausbildungsbetriebe?",o:["Die Ausbildungsberater der Handwerkskammer","Die Berufsgenossenschaft des Gewerks","Das Gewerbeamt der Gemeinde","Die Lehrer der Berufsschule"],a:0,e:"Die Handwerkskammer überwacht die Ausbildung und berät Betriebe und Azubis. Dafür setzt sie Ausbildungsberater ein.",l:"HwO § 41a",t:"Zuständige Stelle",s:"leicht",p:"Entwurf, Fachprüfung offen"},
 {id:"T4-1-19",hf:"IV-1",q:"Welcher Nutzen der eigenen Ausbildung ist für einen Handwerksbetrieb am wichtigsten?",o:["Azubis sind billige Arbeitskräfte für einfache Hilfsarbeiten.","Der Betrieb sichert sich eigene Fachkräfte, die er kennt und die den Betrieb kennen.","Der Betrieb spart die Steuer auf die Vergütung.","Der Betrieb muss keine Gesellen mehr einstellen."],a:1,e:"Wer selbst ausbildet, bekommt Fachkräfte, die die Abläufe und Kunden schon kennen. Das spart Suche und Einarbeitung. Azubis dürfen nur Aufgaben bekommen, die der Ausbildung dienen.",l:"Rahmenplan AEVO, Handlungsfeld 1",t:"Nutzen der Ausbildung",s:"leicht",p:"Entwurf, Fachprüfung offen"},
 {id:"T4-4-12",hf:"IV-4",q:"Wie oft darf ein Prüfling eine nicht bestandene Gesellenprüfung wiederholen?",o:["Gar nicht","Einmal","Zweimal","Beliebig oft"],a:2,e:"Die Gesellenprüfung kann zweimal wiederholt werden. Gute Teilergebnisse können auf Antrag angerechnet werden.",l:"HwO § 31 Abs. 1",t:"Gesellenprüfung",s:"leicht",p:"Entwurf, Fachprüfung offen"},
 {id:"T4-4-13",hf:"IV-4",q:"Wozu dient die Zwischenprüfung?",o:["Sie entscheidet, ob die Ausbildung weitergeht.","Sie zeigt, wo der Azubi in der Ausbildung steht.","Sie ersetzt die Berufsschulnoten.","Sie ist freiwillig und hat keine Bedeutung."],a:1,e:"Die Zwischenprüfung ermittelt den Ausbildungsstand. Betrieb und Azubi sehen, wo noch Lücken sind. Die Teilnahme ist Voraussetzung für die Zulassung zur Gesellenprüfung, das Ergebnis aber nicht.",l:"HwO § 39, HwO § 36",t:"Zwischenprüfung",s:"mittel",p:"Entwurf, Fachprüfung offen"},
 {id:"T4-4-14",hf:"IV-4",q:"Was ist das Besondere an einer gestreckten Gesellenprüfung?",o:["Sie dauert drei Tage am Stück direkt nach der Ausbildung.","Sie findet nur in der Berufsschule statt, ohne Prüfungsausschuss.","Es gibt nur einen schriftlichen Teil und keine praktische Prüfung.","Zwei Teile zu verschiedenen Zeiten, beide zählen für das Ergebnis."],a:3,e:"Bei der gestreckten Gesellenprüfung gibt es Teil 1 etwa in der Mitte und Teil 2 am Ende der Ausbildung. Anders als die Zwischenprüfung zählt Teil 1 schon für das Gesamtergebnis.",l:"HwO § 36a",t:"Gesellenprüfung",s:"mittel",p:"Entwurf, Fachprüfung offen"},
 {id:"T4-4-15",hf:"IV-4",q:"Muss der Betrieb den Azubi vor der schriftlichen Abschlussprüfung freistellen?",o:["Nein, freistellen muss er nur am Prüfungstag selbst.","Ja, auch am Arbeitstag direkt vor der schriftlichen Prüfung.","Nur wenn der Azubi noch unter 18 Jahre alt ist.","Nur wenn es im Tarifvertrag oder Arbeitsvertrag steht."],a:1,e:"Der Betrieb muss für die Prüfung freistellen und zusätzlich für den Arbeitstag, der der schriftlichen Abschlussprüfung direkt vorangeht. Das gilt für alle Azubis, egal wie alt.",l:"BBiG § 15 Abs. 1 Nr. 5",t:"Freistellung",s:"mittel",p:"Entwurf, Fachprüfung offen"}
];

